{
	"mcpServers": {
		"grep_app": {
			"url": "https://mcp.grep.app"
		},
		"context7": {
			"url": "https://mcp.context7.com/mcp"
		},
		"codegraph": {
			"command": "node",
			"args": ["components/codegraph/dist/serve.js"],
			"cwd": ".",
			"required": false
		},
		"git_bash": {
			"command": "node",
			"args": ["../../git-bash-mcp/dist/cli.js", "mcp"],
			"cwd": "."
		},
		"lsp": {
			"command": "node",
			"args": ["../../lsp-daemon/dist/cli.js", "mcp"],
			"cwd": "."
		}
	}
}

{
	"hooks": {
		"SessionStart": [
			{
				"hooks": [
					{
						"type": "command",
						"command": "node \"${PLUGIN_ROOT}/components/bootstrap/dist/cli.js\" hook session-start",
						"commandWindows": "powershell -NoProfile -ExecutionPolicy Bypass -File \"${PLUGIN_ROOT}\\components\\bootstrap\\scripts\\bootstrap.ps1\"",
						"timeout": 30,
						"statusMessage": "(OmO) Checking Bootstrap Provisioning"
					}
				]
			}
		]
	}
}

{
	"name": "node",
	"platforms": {
		"win32-x64": {
			"sha256": "edaca9bd58ec8e92037dac4e877d52f6b8f430b81c18b57e264b4e2fb111cd56",
			"url": "https://nodejs.org/dist/v24.16.0/node-v24.16.0-win-x64.zip"
		}
	},
	"version": "24.16.0"
}

{
	"name": "@sisyphuslabs/codex-bootstrap",
	"version": "4.13.0",
	"description": "Codex SessionStart bootstrap component that provisions LazyCodex runtime dependencies from a detached worker.",
	"type": "module",
	"private": true,
	"files": [
		"dist",
		"hooks",
		"scripts",
		"manifests"
	],
	"scripts": {
		"build": "node scripts/build.mjs",
		"test": "bun test test/*.test.ts"
	},
	"engines": {
		"node": ">=20.0.0"
	}
}

# LazyCodex bootstrap SessionStart hook for native Windows (Windows PowerShell 5.1).
# Codex runs hooks through %COMSPEC%, so node may be absent from PATH entirely;
# this script provisions it silently: node on PATH -> common install dirs ->
# winget OpenJS.NodeJS.LTS -> portable ZIP pinned by manifests/node.json
# (sha256-verified, extracted under <codexHome>\runtime\node, USER PATH append).
# Git Bash is prepared best-effort on the provisioning path, then the script
# delegates to the bundled node hook. It always exits 0: provisioning failures
# are logged to $env:PLUGIN_DATA\bootstrap\ps-bootstrap.log, never block a session.

$ErrorActionPreference = "Continue"
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

$script:LogPath = $null
$script:DoctorHint = "npx lazycodex-ai doctor"
$script:NonGitBashLauncherDirSegments = @("\windows\system32\", "\microsoft\windowsapps\")

function Initialize-BootstrapLog {
	if ([string]::IsNullOrWhiteSpace($env:PLUGIN_DATA)) { return }
	try {
		$logDirectory = Join-Path $env:PLUGIN_DATA "bootstrap"
		if (-not (Test-Path -LiteralPath $logDirectory)) {
			New-Item -ItemType Directory -Path $logDirectory -Force | Out-Null
		}
		$script:LogPath = Join-Path $logDirectory "ps-bootstrap.log"
	} catch {
		$script:LogPath = $null
	}
}

function Write-BootstrapLog {
	param([string]$Message)
	if ($null -eq $script:LogPath) { return }
	try {
		$stamp = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")
		Add-Content -LiteralPath $script:LogPath -Value ($stamp + " " + $Message) -Encoding ASCII
	} catch { }
}

function Resolve-CodexHome {
	if (-not [string]::IsNullOrWhiteSpace($env:CODEX_HOME)) { return $env:CODEX_HOME.Trim() }
	if (-not [string]::IsNullOrWhiteSpace($env:PLUGIN_ROOT)) {
		$current = $env:PLUGIN_ROOT
		for ($level = 0; $level -lt 6; $level += 1) {
			$parent = Split-Path -Path $current -Parent
			if ([string]::IsNullOrEmpty($parent) -or ($parent -eq $current)) { break }
			$current = $parent
			if (Test-Path -LiteralPath (Join-Path $current "config.toml") -PathType Leaf) { return $current }
		}
	}
	return (Join-Path $env:USERPROFILE ".codex")
}

function Get-NodeManifest {
	$manifestPath = Join-Path $env:PLUGIN_ROOT "components\bootstrap\manifests\node.json"
	if (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf)) {
		Write-BootstrapLog ("degraded component=node reason=manifest-missing path=" + $manifestPath + " hint=" + $script:DoctorHint)
		return $null
	}
	try {
		return (Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json)
	} catch {
		Write-BootstrapLog ("degraded component=node reason=manifest-unparsable path=" + $manifestPath + " hint=" + $script:DoctorHint)
		return $null
	}
}

function Get-PortableNodeDirectory {
	param([string]$CodexHome, $Manifest)
	$runtimeRoot = Join-Path $CodexHome "runtime\node"
	return (Join-Path $runtimeRoot ("node-v" + $Manifest.version + "-win-x64"))
}

function Resolve-NodeCommand {
	param([string]$CodexHome, $Manifest)
	$onPath = Get-Command node -CommandType Application -ErrorAction SilentlyContinue
	if ($null -ne $onPath) {
		return (@($onPath)[0]).Source
	}
	$candidateDirectories = @()
	if (-not [string]::IsNullOrWhiteSpace($env:ProgramFiles)) {
		$candidateDirectories += (Join-Path $env:ProgramFiles "nodejs")
	}
	if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
		$candidateDirectories += (Join-Path $env:LOCALAPPDATA "Programs\nodejs")
	}
	if ($null -ne $Manifest) {
		$candidateDirectories += (Get-PortableNodeDirectory -CodexHome $CodexHome -Manifest $Manifest)
	}
	foreach ($directory in $candidateDirectories) {
		$candidate = Join-Path $directory "node.exe"
		if (Test-Path -LiteralPath $candidate -PathType Leaf) { return $candidate }
	}
	return $null
}

function Install-NodeWithWinget {
	$winget = Get-Command winget -ErrorAction SilentlyContinue
	if ($null -eq $winget) {
		Write-BootstrapLog "winget unavailable; skipping winget node install"
		return
	}
	Write-BootstrapLog "installing node via: winget install OpenJS.NodeJS.LTS --silent"
	try {
		& winget install OpenJS.NodeJS.LTS --silent --accept-package-agreements --accept-source-agreements | Out-Null
		Write-BootstrapLog ("winget node install finished with exit code " + $LASTEXITCODE)
	} catch {
		Write-BootstrapLog ("winget node install failed: " + $_.Exception.Message)
	}
}

function Add-UserPathEntry {
	param([string]$Directory)
	$normalizedTarget = $Directory.TrimEnd("\")
	$currentPath = [Environment]::GetEnvironmentVariable("Path", "User")
	if ($null -eq $currentPath) { $currentPath = "" }
	foreach ($entry in $currentPath.Split(";")) {
		if ($entry.Trim().TrimEnd("\") -eq $normalizedTarget) {
			Write-BootstrapLog ("user PATH already contains " + $Directory + "; leaving it unchanged")
			return
		}
	}
	if ($currentPath.Trim().Length -eq 0) {
		$updatedPath = $Directory
	} else {
		$updatedPath = $currentPath.TrimEnd(";") + ";" + $Directory
	}
	[Environment]::SetEnvironmentVariable("Path", $updatedPath, "User")
	Write-BootstrapLog ("appended " + $Directory + " to the USER PATH; restart Codex so new sessions can see node")
}

function Install-PortableNode {
	param([string]$CodexHome, $Manifest)
	if ($null -eq $Manifest) { return $null }
	$platformEntry = $Manifest.platforms."win32-x64"
	if ($null -eq $platformEntry) {
		Write-BootstrapLog ("degraded component=node reason=manifest-missing-win32-x64 hint=" + $script:DoctorHint)
		return $null
	}
	$zipPath = Join-Path $env:TEMP ("lazycodex-node-v" + $Manifest.version + "-win-x64.zip")
	Write-BootstrapLog ("downloading portable node from " + $platformEntry.url)
	try {
		Invoke-WebRequest -Uri $platformEntry.url -OutFile $zipPath -UseBasicParsing
	} catch {
		Write-BootstrapLog ("degraded component=node reason=download-failed url=" + $platformEntry.url + " error=" + $_.Exception.Message + " hint=" + $script:DoctorHint)
		return $null
	}
	$expectedHash = ([string]$platformEntry.sha256).ToLowerInvariant()
	$actualHash = (Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash.ToLowerInvariant()
	if ($actualHash -ne $expectedHash) {
		Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
		Write-BootstrapLog ("degraded component=node reason=sha256-mismatch expected=" + $expectedHash + " actual=" + $actualHash + " hint=" + $script:DoctorHint)
		return $null
	}
	$runtimeRoot = Join-Path $CodexHome "runtime\node"
	try {
		if (-not (Test-Path -LiteralPath $runtimeRoot)) {
			New-Item -ItemType Directory -Path $runtimeRoot -Force | Out-Null
		}
		Expand-Archive -LiteralPath $zipPath -DestinationPath $runtimeRoot -Force
	} catch {
		Write-BootstrapLog ("degraded component=node reason=extract-failed error=" + $_.Exception.Message + " hint=" + $script:DoctorHint)
		return $null
	} finally {
		Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue
	}
	$nodeDirectory = Get-PortableNodeDirectory -CodexHome $CodexHome -Manifest $Manifest
	$nodeExe = Join-Path $nodeDirectory "node.exe"
	if (-not (Test-Path -LiteralPath $nodeExe -PathType Leaf)) {
		Write-BootstrapLog ("degraded component=node reason=extracted-layout-unexpected expected=" + $nodeExe + " hint=" + $script:DoctorHint)
		return $null
	}
	Write-BootstrapLog ("portable node provisioned at " + $nodeExe)
	Add-UserPathEntry -Directory $nodeDirectory
	return $nodeExe
}

function Test-KnownNonGitBashLauncher {
	param([string]$CandidatePath)
	$normalized = $CandidatePath.Replace("/", "\").ToLowerInvariant()
	foreach ($segment in $script:NonGitBashLauncherDirSegments) {
		if ($normalized.Contains($segment)) { return $true }
	}
	return $false
}

function Resolve-GitBash {
	if (-not [string]::IsNullOrWhiteSpace($env:OMO_CODEX_GIT_BASH_PATH)) {
		$envCandidate = $env:OMO_CODEX_GIT_BASH_PATH.Trim()
		if ($envCandidate.ToLowerInvariant().EndsWith("bash.exe") -and (Test-Path -LiteralPath $envCandidate -PathType Leaf)) {
			return @{ Path = $envCandidate; Source = "env" }
		}
		return $null
	}
	$programFilesCandidates = @()
	if (-not [string]::IsNullOrWhiteSpace($env:ProgramFiles)) {
		$programFilesCandidates += (Join-Path $env:ProgramFiles "Git\bin\bash.exe")
	}
	$programFilesX86 = ${env:ProgramFiles(x86)}
	if (-not [string]::IsNullOrWhiteSpace($programFilesX86)) {
		$programFilesCandidates += (Join-Path $programFilesX86 "Git\bin\bash.exe")
	}
	foreach ($candidate in $programFilesCandidates) {
		if (Test-Path -LiteralPath $candidate -PathType Leaf) {
			return @{ Path = $candidate; Source = "program-files" }
		}
	}
	$whereOutput = @()
	try { $whereOutput = & where.exe bash 2>$null } catch { $whereOutput = @() }
	foreach ($rawLine in @($whereOutput)) {
		if ($null -eq $rawLine) { continue }
		$candidate = ([string]$rawLine).Trim()
		if ($candidate.Length -eq 0) { continue }
		if (Test-KnownNonGitBashLauncher -CandidatePath $candidate) { continue }
		if ($candidate.ToLowerInvariant().EndsWith("bash.exe") -and (Test-Path -LiteralPath $candidate -PathType Leaf)) {
			return @{ Path = $candidate; Source = "path" }
		}
	}
	return $null
}

function Initialize-GitBash {
	$resolution = Resolve-GitBash
	if (($null -eq $resolution) -and ($env:OMO_CODEX_SKIP_GIT_BASH_AUTO_INSTALL -ne "1")) {
		$winget = Get-Command winget -ErrorAction SilentlyContinue
		if ($null -ne $winget) {
			Write-BootstrapLog "installing git bash via: winget install --id Git.Git -e --source winget"
			try {
				& winget install --id Git.Git -e --source winget | Out-Null
				Write-BootstrapLog ("winget git install finished with exit code " + $LASTEXITCODE)
			} catch {
				Write-BootstrapLog ("winget git install failed: " + $_.Exception.Message)
			}
			$resolution = Resolve-GitBash
		} else {
			Write-BootstrapLog "winget unavailable; skipping git bash install"
		}
	}
	if ($null -eq $resolution) {
		Write-BootstrapLog ("degraded component=git_bash reason=not-found install=winget install --id Git.Git -e --source winget hint=" + $script:DoctorHint)
		return
	}
	Write-BootstrapLog ("git bash resolved at " + $resolution.Path + " source=" + $resolution.Source)
	if ($resolution.Source -eq "path") {
		$persisted = [Environment]::GetEnvironmentVariable("OMO_CODEX_GIT_BASH_PATH", "User")
		if ([string]::IsNullOrWhiteSpace($persisted)) {
			[Environment]::SetEnvironmentVariable("OMO_CODEX_GIT_BASH_PATH", $resolution.Path, "User")
			Write-BootstrapLog ("persisted OMO_CODEX_GIT_BASH_PATH=" + $resolution.Path + " in the USER environment; restart Codex to pick it up")
		}
	}
}

function Invoke-NodeHookDelegate {
	param([string]$NodeExe)
	$hookCli = Join-Path $env:PLUGIN_ROOT "components\bootstrap\dist\cli.js"
	if (-not (Test-Path -LiteralPath $hookCli -PathType Leaf)) {
		Write-BootstrapLog ("degraded component=bootstrap reason=hook-cli-missing path=" + $hookCli + " hint=" + $script:DoctorHint)
		return
	}
	Write-BootstrapLog ("delegating to node hook: " + $NodeExe + " " + $hookCli + " hook session-start")
	& $NodeExe $hookCli hook session-start
	Write-BootstrapLog ("node hook exited with code " + $LASTEXITCODE)
}

function Write-ProvisioningIncompleteNotice {
	$notice = "LazyCodex bootstrap: Node.js is not available yet. Install Node LTS (winget install OpenJS.NodeJS.LTS), then restart Codex. Diagnose with: " + $script:DoctorHint
	$payload = @{
		hookSpecificOutput = @{
			hookEventName = "SessionStart"
			additionalContext = $notice
		}
	}
	Write-Output (ConvertTo-Json -InputObject $payload -Compress -Depth 4)
}

function Invoke-Bootstrap {
	Initialize-BootstrapLog
	Write-BootstrapLog "bootstrap.ps1 session-start begin"
	if ([string]::IsNullOrWhiteSpace($env:PLUGIN_ROOT)) {
		Write-BootstrapLog "PLUGIN_ROOT missing; skipping bootstrap"
		return
	}
	$codexHome = Resolve-CodexHome
	Write-BootstrapLog ("codex home resolved to " + $codexHome)
	$manifest = Get-NodeManifest
	$nodeExe = Resolve-NodeCommand -CodexHome $codexHome -Manifest $manifest
	if ($null -ne $nodeExe) {
		Write-BootstrapLog ("node already available at " + $nodeExe)
		Invoke-NodeHookDelegate -NodeExe $nodeExe
		return
	}
	Install-NodeWithWinget
	$nodeExe = Resolve-NodeCommand -CodexHome $codexHome -Manifest $manifest
	if ($null -eq $nodeExe) {
		$nodeExe = Install-PortableNode -CodexHome $codexHome -Manifest $manifest
	}
	Initialize-GitBash
	if ($null -eq $nodeExe) {
		Write-BootstrapLog ("degraded component=node reason=unresolved hint=" + $script:DoctorHint)
		Write-ProvisioningIncompleteNotice
		return
	}
	Invoke-NodeHookDelegate -NodeExe $nodeExe
}

try {
	Invoke-Bootstrap
} catch {
	try { Write-BootstrapLog ("unhandled bootstrap error: " + $_.Exception.Message) } catch { }
}
exit 0

#!/usr/bin/env node
import { spawnSync } from "node:child_process";
import { existsSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const componentRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const bundlePath = join(componentRoot, "dist", "cli.js");

const result = spawnSync(
	"bun",
	["x", "esbuild", "src/cli.ts", "--bundle", "--platform=node", "--format=esm", "--outfile=dist/cli.js"],
	{
		cwd: componentRoot,
		shell: process.platform === "win32",
		stdio: "inherit",
	},
);

if (result.error === undefined && result.status === 0) {
	process.exit(0);
}

if (hasBundledDist()) {
	console.log("Using bundled bootstrap dist");
	process.exit(0);
}

console.error(`Bootstrap bundle failed and no bundled dist exists at ${bundlePath}.`);
console.error("Install Bun (used via `bun x esbuild`) or ship a prebuilt dist/cli.js.");
process.exit(result.status === null || result.status === undefined || result.status === 0 ? 1 : result.status);

function hasBundledDist() {
	return existsSync(bundlePath) && statSync(bundlePath).size > 0;
}

#!/usr/bin/env node
// Regenerates the committed, reviewed manifest at ../manifests/node.json.
// This script is the ONLY network-touching code in the bootstrap component; runtime
// downloads consume the pinned values, and unit tests inject fetch (never the network).
//
// Re-run procedure to move the pinned Node.js LTS:
//   1. node packages/omo-codex/plugin/components/bootstrap/scripts/generate-manifests.mjs
//      [--node-version <x.y.z>]
//   2. Review the manifest diff and commit it. Manifests are NEVER generated at build
//      time; builds must stay offline and deterministic.
//
// Sources:
//   - node: https://nodejs.org/dist (SHASUMS256.txt per release; win32-x64 zip only)
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const componentRoot = dirname(scriptDirectory);
const manifestsDirectory = join(componentRoot, "manifests");

function parseArgs(argv) {
	const flags = {};
	for (let index = 0; index < argv.length; index += 1) {
		if (argv[index] === "--node-version") flags.nodeVersion = argv[(index += 1)];
		else throw new Error(`unknown argument: ${argv[index]}`);
	}
	return flags;
}

async function fetchOk(url, accept) {
	const headers = { "user-agent": "lazycodex-generate-manifests" };
	if (accept) headers.accept = accept;
	if (process.env.GITHUB_TOKEN && url.startsWith("https://api.github.com/")) {
		headers.authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
	}
	const response = await fetch(url, { headers });
	if (!response.ok) throw new Error(`GET ${url} -> HTTP ${response.status}`);
	return response;
}

async function resolveLatestNodeLtsVersion() {
	const releases = await (await fetchOk("https://nodejs.org/dist/index.json")).json();
	const latestLts = releases.find((release) => release.lts !== false);
	if (latestLts === undefined) throw new Error("nodejs.org/dist/index.json contains no LTS release");
	console.log(`node: latest LTS ${latestLts.version} (${latestLts.lts})`);
	return latestLts.version.replace(/^v/, "");
}

async function generateNodeManifest(version) {
	const zipName = `node-v${version}-win-x64.zip`;
	const shasums = await (await fetchOk(`https://nodejs.org/dist/v${version}/SHASUMS256.txt`)).text();
	const line = shasums.split("\n").find((candidate) => candidate.trim().endsWith(`  ${zipName}`) || candidate.trim().endsWith(` ${zipName}`));
	if (line === undefined) throw new Error(`SHASUMS256.txt for v${version} has no entry for ${zipName}`);
	const sha256 = line.trim().split(/\s+/)[0];
	if (!/^[a-f0-9]{64}$/.test(sha256)) throw new Error(`invalid sha256 parsed for ${zipName}: ${sha256}`);
	const url = `https://nodejs.org/dist/v${version}/${zipName}`;
	console.log(`node win32-x64: ${zipName} sha256=${sha256}`);
	return { name: "node", platforms: { "win32-x64": { sha256, url } }, version };
}

async function writeManifest(fileName, manifest) {
	const path = join(manifestsDirectory, fileName);
	await mkdir(manifestsDirectory, { recursive: true });
	await writeFile(path, `${JSON.stringify(manifest, null, "\t")}\n`, "utf8");
	console.log(`wrote ${path}`);
}

const flags = parseArgs(process.argv.slice(2));
const nodeVersion = flags.nodeVersion ?? (await resolveLatestNodeLtsVersion());
await writeManifest("node.json", await generateNodeManifest(nodeVersion));

#!/usr/bin/env node
import { realpathSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { downloadFromManifest } from "./download.ts";
import { runSessionStartHook } from "./hook.ts";
import { runBootstrapWorker } from "./worker.ts";

export {
	bootstrapLocks,
	detectInstallFlow,
	detectInstallFlowDetailed,
	detectInstallFlowForTest,
	detectInstallFlowFromEnvironment,
	INSTALL_SNAPSHOT_FILENAME,
	resolveBootstrapLockPath,
	resolveBootstrapStatePath,
	resolveCodexHome,
} from "./environment.ts";
export type {
	BootstrapLockHandle,
	BootstrapLocksOptions,
	CodexHomeResolution,
	CodexHomeSource,
	ConfigSourceSignal,
	DetectInstallFlowFromEnvironmentOptions,
	DetectInstallFlowOptions,
	InstallFlow,
	InstallFlowDetection,
	ResolveCodexHomeOptions,
} from "./environment.ts";
export { BOOTSTRAP_RESTART_NOTICE, executeSessionStartHook, runSessionStartHook } from "./hook.ts";
export {
	runSgProvision,
	SG_FORCE_PROVISION_ENV_KEY,
	SG_PROVISION_COMPONENT,
	sgProvisionDestination,
} from "./provision.ts";
export type { ResolvePreexistingSgOptions, SgProvisionSeams } from "./provision.ts";
export { GIT_BASH_INSTALL_HINT, runWorkerSetup, SETUP_MARKETPLACE_NAME, SETUP_PLUGIN_NAME } from "./setup.ts";
export type { SetupRunCommand, WorkerSetupOptions } from "./setup.ts";
export type {
	SessionStartAction,
	SessionStartHookOptions,
	SessionStartHookResult,
	WorkerSpawnInvocation,
} from "./hook.ts";
export {
	appendBootstrapLog,
	BOOTSTRAP_DOCTOR_HINT,
	defaultWorkerSteps,
	parseBootstrapState,
	parseWorkerFlags,
	readBootstrapState,
	readPluginVersion,
	resolvePluginDataRoot,
	runBootstrapWorker,
} from "./worker.ts";
export type {
	DefaultWorkerStepsSeams,
	BootstrapDegradedEntry,
	BootstrapRunStatus,
	BootstrapState,
	BootstrapStepOutcome,
	BootstrapWorkerContext,
	BootstrapWorkerFlags,
	BootstrapWorkerResult,
	BootstrapWorkerSkipReason,
	BootstrapWorkerStep,
	RunBootstrapWorkerOptions,
} from "./worker.ts";

const TOP_LEVEL_HELP =
	"Usage:\n  omo-bootstrap hook session-start\n  omo-bootstrap worker [--codex-home <dir>] [--once] [--only <step>] [--manifest-dir <dir>]\n  omo-bootstrap download <manifest> <platform> <destination-dir>\n  omo-bootstrap help | --help | -h\n";

async function runDownloadCommand(args: readonly string[]): Promise<number> {
	const [manifestName, platformKey, destinationDir] = args;
	if (manifestName === undefined || platformKey === undefined || destinationDir === undefined) {
		process.stderr.write(`[omo-bootstrap] download requires <manifest> <platform> <destination-dir>\n${TOP_LEVEL_HELP}`);
		return 1;
	}
	try {
		const destination = await downloadFromManifest({ destinationDir, manifestName, platformKey });
		process.stdout.write(`OK:${destination}\n`);
		return 0;
	} catch (error) {
		process.stderr.write(`[omo-bootstrap] download failed: ${error instanceof Error ? error.message : String(error)}\n`);
		return 1;
	}
}

async function runWorkerCommand(args: readonly string[]): Promise<number> {
	let result;
	try {
		result = await runBootstrapWorker({ argv: args, env: process.env });
	} catch (error) {
		const message = error instanceof Error ? error.message : String(error);
		if (/flag/.test(message)) {
			process.stderr.write(`[omo-bootstrap] ${message}\n${TOP_LEVEL_HELP}`);
			return 1;
		}
		// Runtime worker failures must never surface as non-zero exits; the
		// degraded ledger in state.json is the error channel.
		process.stderr.write(`[omo-bootstrap] worker error: ${message}\n`);
		return 0;
	}
	process.stdout.write(
		result.ran ? `[omo-bootstrap] worker finished: ${result.status}\n` : `[omo-bootstrap] worker skipped: ${result.reason}\n`,
	);
	return 0;
}

async function main(): Promise<number> {
	const argv = process.argv.slice(2);
	const command = argv[0];
	if (command === undefined || command === "help" || command === "--help" || command === "-h") {
		process.stdout.write(TOP_LEVEL_HELP);
		return 0;
	}
	if (command === "hook" && argv[1] === "session-start") {
		return runSessionStartHook({ env: process.env, stdin: process.stdin });
	}
	if (command === "worker") {
		return runWorkerCommand(argv.slice(1));
	}
	if (command === "download") {
		return runDownloadCommand(argv.slice(1));
	}
	process.stderr.write(`[omo-bootstrap] unknown command: ${argv.join(" ")}\n${TOP_LEVEL_HELP}`);
	return 1;
}

function isProcessEntry(): boolean {
	const entry = process.argv[1];
	if (entry === undefined) return false;
	try {
		return realpathSync(entry) === realpathSync(fileURLToPath(import.meta.url));
	} catch {
		return false;
	}
}

if (isProcessEntry()) {
	main()
		.then((code) => {
			process.exit(code);
		})
		.catch((error: unknown) => {
			// The SessionStart hook path must never fail the session: log and exit 0.
			process.stderr.write(`[omo-bootstrap] ${error instanceof Error ? error.message : String(error)}\n`);
			process.exit(0);
		});
}

import { createHash, randomUUID } from "node:crypto";
import { createWriteStream } from "node:fs";
import { mkdir, readFile, rename, rm } from "node:fs/promises";
import { basename, dirname, join } from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import type { ReadableStream as NodeWebReadableStream } from "node:stream/web";
import { fileURLToPath } from "node:url";

export type DownloadErrorCode = "checksum-mismatch" | "download-failed" | "unsupported-platform";

export class DownloadError extends Error {
	readonly code: DownloadErrorCode;

	constructor(code: DownloadErrorCode, message: string) {
		super(message);
		this.name = "DownloadError";
		this.code = code;
	}
}

export class ChecksumMismatchError extends DownloadError {
	readonly expectedSha256: string;
	readonly actualSha256: string;

	constructor(options: { readonly url: string; readonly expectedSha256: string; readonly actualSha256: string }) {
		super(
			"checksum-mismatch",
			`Checksum mismatch for ${options.url}: expected sha256 ${options.expectedSha256} but downloaded sha256 ${options.actualSha256}; deleted the partial download.`,
		);
		this.name = "ChecksumMismatchError";
		this.expectedSha256 = options.expectedSha256;
		this.actualSha256 = options.actualSha256;
	}
}

export class UnsupportedPlatformError extends DownloadError {
	readonly manifestName: string;
	readonly platformKey: string;

	constructor(options: {
		readonly manifestName: string;
		readonly platformKey: string;
		readonly availablePlatforms: readonly string[];
	}) {
		super(
			"unsupported-platform",
			`Manifest "${options.manifestName}" has no asset for unsupported platform "${options.platformKey}" (available: ${options.availablePlatforms.join(", ")}).`,
		);
		this.name = "UnsupportedPlatformError";
		this.manifestName = options.manifestName;
		this.platformKey = options.platformKey;
	}
}

export type FetchLike = (url: string) => Promise<Response>;

export interface ManifestAsset {
	readonly url: string;
	readonly sha256: string;
}

export interface AssetManifest {
	readonly name: string;
	readonly version: string;
	readonly platforms: Readonly<Record<string, ManifestAsset>>;
}

export interface DownloadChecksummedAssetOptions {
	readonly url: string;
	readonly sha256: string;
	readonly destination: string;
	readonly fetchImpl?: FetchLike;
	readonly env?: NodeJS.ProcessEnv;
}

export interface DownloadFromManifestOptions {
	readonly manifestName: string;
	readonly platformKey: string;
	readonly destinationDir: string;
	readonly fetchImpl?: FetchLike;
	readonly env?: NodeJS.ProcessEnv;
	readonly manifestsDir?: string;
}

const PROXY_ENV_KEYS = ["HTTPS_PROXY", "https_proxy", "HTTP_PROXY", "http_proxy"] as const;

function proxyLimitationNote(env: NodeJS.ProcessEnv): string {
	const configuredKey = PROXY_ENV_KEYS.find((key) => (env[key] ?? "").trim().length > 0);
	if (configuredKey === undefined) return "";
	return ` Note: ${configuredKey} is set, but the bootstrap downloader does not tunnel through HTTP(S) proxies in v1; the download was attempted directly.`;
}

function describeFailure(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

async function writeBodyToFile(body: NodeWebReadableStream<Uint8Array> | null, tempPath: string): Promise<string> {
	const hash = createHash("sha256");
	if (body === null) {
		await pipeline(Readable.from([]), createWriteStream(tempPath));
		return hash.digest("hex");
	}
	await pipeline(
		Readable.fromWeb(body),
		async function* hashChunks(source: AsyncIterable<Uint8Array>): AsyncGenerator<Buffer> {
			for await (const chunk of source) {
				const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
				hash.update(buffer);
				yield buffer;
			}
		},
		createWriteStream(tempPath),
	);
	return hash.digest("hex");
}

export async function downloadChecksummedAsset(options: DownloadChecksummedAssetOptions): Promise<string> {
	const fetchImpl = options.fetchImpl ?? globalThis.fetch;
	const env = options.env ?? process.env;
	const expectedSha256 = options.sha256.toLowerCase();
	await mkdir(dirname(options.destination), { recursive: true });
	const tempPath = `${options.destination}.${randomUUID().slice(0, 8)}.partial`;

	let response: Response;
	try {
		response = await fetchImpl(options.url);
	} catch (error) {
		throw new DownloadError(
			"download-failed",
			`Download failed for ${options.url}: ${describeFailure(error)}.${proxyLimitationNote(env)}`,
		);
	}
	if (!response.ok) {
		throw new DownloadError(
			"download-failed",
			`Download failed for ${options.url}: HTTP ${response.status}.${proxyLimitationNote(env)}`,
		);
	}

	let actualSha256: string;
	try {
		actualSha256 = await writeBodyToFile(response.body as NodeWebReadableStream<Uint8Array> | null, tempPath);
	} catch (error) {
		await rm(tempPath, { force: true });
		throw new DownloadError(
			"download-failed",
			`Download failed for ${options.url} while writing the response body: ${describeFailure(error)}.${proxyLimitationNote(env)}`,
		);
	}

	if (actualSha256 !== expectedSha256) {
		await rm(tempPath, { force: true });
		throw new ChecksumMismatchError({ actualSha256, expectedSha256, url: options.url });
	}

	await rename(tempPath, options.destination);
	return options.destination;
}

export function resolveDefaultManifestsDir(): string {
	return join(dirname(fileURLToPath(import.meta.url)), "..", "manifests");
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseManifestAsset(value: unknown, manifestName: string, platformKey: string): ManifestAsset {
	if (!isRecord(value) || typeof value["url"] !== "string" || typeof value["sha256"] !== "string") {
		throw new Error(`Manifest "${manifestName}" platform "${platformKey}" must pin both url and sha256 strings.`);
	}
	return { sha256: value["sha256"], url: value["url"] };
}

export function parseAssetManifest(raw: string, manifestName: string): AssetManifest {
	const data: unknown = JSON.parse(raw);
	if (!isRecord(data) || typeof data["name"] !== "string" || typeof data["version"] !== "string" || !isRecord(data["platforms"])) {
		throw new Error(`Manifest "${manifestName}" must declare name, version, and a platforms object.`);
	}
	const platforms: Record<string, ManifestAsset> = {};
	for (const [platformKey, asset] of Object.entries(data["platforms"])) {
		platforms[platformKey] = parseManifestAsset(asset, manifestName, platformKey);
	}
	return { name: data["name"], platforms, version: data["version"] };
}

export async function loadAssetManifest(manifestName: string, manifestsDir?: string): Promise<AssetManifest> {
	const directory = manifestsDir ?? resolveDefaultManifestsDir();
	const raw = await readFile(join(directory, `${manifestName}.json`), "utf8");
	return parseAssetManifest(raw, manifestName);
}

export async function downloadFromManifest(options: DownloadFromManifestOptions): Promise<string> {
	const manifest = await loadAssetManifest(options.manifestName, options.manifestsDir);
	const asset = manifest.platforms[options.platformKey];
	if (asset === undefined) {
		throw new UnsupportedPlatformError({
			availablePlatforms: Object.keys(manifest.platforms),
			manifestName: options.manifestName,
			platformKey: options.platformKey,
		});
	}
	const destination = join(options.destinationDir, basename(new URL(asset.url).pathname));
	return downloadChecksummedAsset({
		destination,
		sha256: asset.sha256,
		url: asset.url,
		...(options.fetchImpl === undefined ? {} : { fetchImpl: options.fetchImpl }),
		...(options.env === undefined ? {} : { env: options.env }),
	});
}

import { stat } from "node:fs/promises";
import { readFile } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";

import { acquireLock, DEFAULT_LOCK_STALE_MS, resolveLockPath, resolveStatePath } from "../../../scripts/auto-update-state.mjs";

export type InstallFlow = "npx-local" | "marketplace" | "unknown";

export type ConfigSourceSignal = "npx-local" | "marketplace" | "unparsable";

export interface DetectInstallFlowOptions {
	readonly pluginRoot: string;
	readonly configToml?: string;
	readonly marketplaceName?: string;
}

export interface InstallFlowDetection {
	readonly flow: InstallFlow;
	readonly snapshotPresent: boolean;
	readonly configSource: string | undefined;
	readonly configSignal: ConfigSourceSignal | undefined;
	readonly reason: string;
}

export const INSTALL_SNAPSHOT_FILENAME = "lazycodex-install.json";

const DEFAULT_MARKETPLACE_NAME = "sisyphuslabs";
const MAX_CODEX_HOME_WALK_UP_LEVELS = 6;

export async function detectInstallFlowDetailed(options: DetectInstallFlowOptions): Promise<InstallFlowDetection> {
	const marketplaceName = options.marketplaceName ?? DEFAULT_MARKETPLACE_NAME;
	const snapshotPresent = await isFile(join(options.pluginRoot, INSTALL_SNAPSHOT_FILENAME));
	const snapshotSignal: InstallFlow = snapshotPresent ? "npx-local" : "marketplace";
	const snapshotReason = snapshotPresent
		? `${INSTALL_SNAPSHOT_FILENAME} present at plugin root (written only by the npx installer)`
		: `${INSTALL_SNAPSHOT_FILENAME} absent from plugin root`;
	const scan = options.configToml === undefined ? { kind: "absent" as const } : scanMarketplaceSource(options.configToml, marketplaceName);

	if (scan.kind === "absent") {
		return {
			configSignal: undefined,
			configSource: undefined,
			flow: snapshotSignal,
			reason: `${snapshotReason}; no [marketplaces.${marketplaceName}] source to cross-check`,
			snapshotPresent,
		};
	}
	if (scan.kind === "unparsable") {
		return {
			configSignal: "unparsable",
			configSource: undefined,
			flow: "unknown",
			reason: `${snapshotReason}; [marketplaces.${marketplaceName}] source value is unparsable`,
			snapshotPresent,
		};
	}
	const configSignal = classifyMarketplaceSource(scan.source);
	if (configSignal === "unparsable") {
		return {
			configSignal,
			configSource: scan.source,
			flow: "unknown",
			reason: `${snapshotReason}; marketplace source ${JSON.stringify(scan.source)} is neither a local absolute path nor a git URL`,
			snapshotPresent,
		};
	}
	if (configSignal !== snapshotSignal) {
		return {
			configSignal,
			configSource: scan.source,
			flow: "unknown",
			reason: `${snapshotReason}, but marketplace source ${JSON.stringify(scan.source)} indicates ${configSignal}; signals disagree`,
			snapshotPresent,
		};
	}
	return {
		configSignal,
		configSource: scan.source,
		flow: snapshotSignal,
		reason: `${snapshotReason}; marketplace source ${JSON.stringify(scan.source)} agrees`,
		snapshotPresent,
	};
}

export async function detectInstallFlow(options: DetectInstallFlowOptions): Promise<InstallFlow> {
	return (await detectInstallFlowDetailed(options)).flow;
}

export interface DetectInstallFlowFromEnvironmentOptions {
	readonly pluginRoot: string;
	readonly env: Record<string, string | undefined>;
	readonly marketplaceName?: string;
}

export async function detectInstallFlowFromEnvironment(
	options: DetectInstallFlowFromEnvironmentOptions,
): Promise<InstallFlowDetection> {
	const home = await resolveCodexHome({ env: options.env, pluginRoot: options.pluginRoot });
	const configToml = await readOptionalFile(join(home.path, "config.toml"));
	return detectInstallFlowDetailed({
		pluginRoot: options.pluginRoot,
		...(configToml === undefined ? {} : { configToml }),
		...(options.marketplaceName === undefined ? {} : { marketplaceName: options.marketplaceName }),
	});
}

export async function detectInstallFlowForTest(pluginRoot: string): Promise<InstallFlow> {
	const home = await resolveCodexHome({ env: {}, pluginRoot });
	const configToml = home.source === "walk-up" ? await readOptionalFile(join(home.path, "config.toml")) : undefined;
	return detectInstallFlow({ pluginRoot, ...(configToml === undefined ? {} : { configToml }) });
}

export type CodexHomeSource = "env" | "walk-up" | "default";

export interface CodexHomeResolution {
	readonly path: string;
	readonly source: CodexHomeSource;
}

export interface ResolveCodexHomeOptions {
	readonly env: Record<string, string | undefined>;
	readonly pluginRoot?: string;
}

export async function resolveCodexHome(options: ResolveCodexHomeOptions): Promise<CodexHomeResolution> {
	const envHome = options.env["CODEX_HOME"]?.trim();
	if (envHome !== undefined && envHome.length > 0) {
		return { path: resolve(envHome), source: "env" };
	}
	if (options.pluginRoot !== undefined) {
		let current = resolve(options.pluginRoot);
		for (let level = 0; level < MAX_CODEX_HOME_WALK_UP_LEVELS; level += 1) {
			const parent = dirname(current);
			if (parent === current) break;
			current = parent;
			if (await isFile(join(current, "config.toml"))) {
				return { path: current, source: "walk-up" };
			}
		}
	}
	return { path: join(homedir(), ".codex"), source: "default" };
}

export interface BootstrapLocksOptions {
	readonly pluginData: string;
	readonly env: Record<string, string | undefined>;
	readonly now?: number;
	readonly staleMs?: number;
}

export interface BootstrapLockHandle {
	readonly statePath: string;
	readonly bootstrapLockPath: string;
	readonly autoUpdateLockPath: string;
	readonly release: () => Promise<void>;
}

export function resolveBootstrapStatePath(pluginData: string): string {
	return join(pluginData, "bootstrap", "state.json");
}

export function resolveBootstrapLockPath(pluginData: string): string {
	return `${resolveBootstrapStatePath(pluginData)}.lock`;
}

export async function bootstrapLocks(options: BootstrapLocksOptions): Promise<BootstrapLockHandle | null> {
	const now = options.now ?? Date.now();
	const staleMs = options.staleMs ?? DEFAULT_LOCK_STALE_MS;
	const statePath = resolveBootstrapStatePath(options.pluginData);
	const bootstrapLockPath = resolveBootstrapLockPath(options.pluginData);
	const autoUpdateLockPath = resolveLockPath(options.env, resolveStatePath(options.env));

	const bootstrapLock = await acquireLock(bootstrapLockPath, now, staleMs);
	if (bootstrapLock === null) return null;
	if (autoUpdateLockPath === bootstrapLockPath) {
		return { autoUpdateLockPath, bootstrapLockPath, release: () => bootstrapLock.release(), statePath };
	}
	const autoUpdateLock = await acquireLock(autoUpdateLockPath, now, staleMs);
	if (autoUpdateLock === null) {
		await bootstrapLock.release();
		return null;
	}
	return {
		autoUpdateLockPath,
		bootstrapLockPath,
		release: async () => {
			await autoUpdateLock.release();
			await bootstrapLock.release();
		},
		statePath,
	};
}

type MarketplaceSourceScan = { readonly kind: "absent" } | { readonly kind: "unparsable" } | { readonly kind: "source"; readonly source: string };

function scanMarketplaceSource(configToml: string, marketplaceName: string): MarketplaceSourceScan {
	const expectedHeaders = new Set([`marketplaces.${marketplaceName}`, `marketplaces.${JSON.stringify(marketplaceName)}`]);
	let inMarketplaceSection = false;
	for (const line of configToml.split("\n")) {
		const header = parseTomlHeader(line);
		if (header !== null) {
			inMarketplaceSection = expectedHeaders.has(header);
			continue;
		}
		if (!inMarketplaceSection) continue;
		const valueText = parseSourceAssignment(line);
		if (valueText === null) continue;
		const source = parseTomlStringValue(valueText);
		return source === undefined ? { kind: "unparsable" } : { kind: "source", source };
	}
	return { kind: "absent" };
}

function parseTomlHeader(line: string): string | null {
	const trimmed = line.trim();
	if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return null;
	if (trimmed.startsWith("[[")) return null;
	return trimmed.slice(1, -1).trim();
}

function parseSourceAssignment(line: string): string | null {
	const match = /^\s*source\s*=\s*(.+)$/.exec(line);
	return match === null ? null : (match[1] ?? null);
}

function parseTomlStringValue(valueText: string): string | undefined {
	const trimmed = valueText.trim();
	if (trimmed.startsWith('"')) return parseLeadingJsonString(trimmed);
	if (trimmed.startsWith("'")) {
		const closingIndex = trimmed.indexOf("'", 1);
		return closingIndex === -1 ? undefined : trimmed.slice(1, closingIndex);
	}
	return undefined;
}

function parseLeadingJsonString(value: string): string | undefined {
	let escaped = false;
	for (let index = 1; index < value.length; index += 1) {
		if (escaped) {
			escaped = false;
			continue;
		}
		const char = value[index];
		if (char === "\\") {
			escaped = true;
			continue;
		}
		if (char === '"') {
			try {
				const parsed: unknown = JSON.parse(value.slice(0, index + 1));
				return typeof parsed === "string" ? parsed : undefined;
			} catch {
				return undefined;
			}
		}
	}
	return undefined;
}

function classifyMarketplaceSource(source: string): ConfigSourceSignal {
	const trimmed = source.trim();
	if (trimmed.length === 0) return "unparsable";
	if (/^(https?|ssh|git):\/\//i.test(trimmed) || trimmed.startsWith("git@")) return "marketplace";
	if (trimmed.startsWith("/") || trimmed.startsWith("~") || trimmed.startsWith("\\\\") || /^[A-Za-z]:[\\/]/.test(trimmed)) {
		return "npx-local";
	}
	if (trimmed.toLowerCase().endsWith(".git")) return "marketplace";
	return "unparsable";
}

async function isFile(path: string): Promise<boolean> {
	try {
		return (await stat(path)).isFile();
	} catch {
		return false;
	}
}

async function readOptionalFile(path: string): Promise<string | undefined> {
	try {
		return await readFile(path, "utf8");
	} catch {
		return undefined;
	}
}

import { spawn } from "node:child_process";
import { stat } from "node:fs/promises";
import type { Readable } from "node:stream";
import { fileURLToPath } from "node:url";

import { DEFAULT_LOCK_STALE_MS } from "../../../scripts/auto-update-state.mjs";
import { resolveBootstrapLockPath, resolveBootstrapStatePath } from "./environment.ts";
import { readBootstrapState, readPluginVersion } from "./worker.ts";

export const BOOTSTRAP_RESTART_NOTICE =
	"LazyCodex bootstrap running in background — restart the session when it completes";

export type SessionStartAction =
	| "spawned"
	| "skip-completed"
	| "skip-locked"
	| "skip-missing-env"
	| "skip-version-unresolved";

export interface WorkerSpawnInvocation {
	readonly command: string;
	readonly args: readonly string[];
	readonly env: Record<string, string | undefined>;
}

export interface SessionStartHookOptions {
	readonly env: Record<string, string | undefined>;
	readonly stdin?: Readable & { readonly isTTY?: boolean };
	readonly now?: number;
	readonly spawnWorker?: (invocation: WorkerSpawnInvocation) => void;
	readonly workerCliPath?: string;
	readonly writeNotice?: (line: string) => void;
}

export interface SessionStartHookResult {
	readonly exitCode: 0;
	readonly action: SessionStartAction;
}

export async function runSessionStartHook(options: SessionStartHookOptions): Promise<number> {
	return (await executeSessionStartHook(options)).exitCode;
}

export async function executeSessionStartHook(options: SessionStartHookOptions): Promise<SessionStartHookResult> {
	if (options.stdin !== undefined) await drainStdin(options.stdin);
	const now = options.now ?? Date.now();
	const pluginRoot = options.env["PLUGIN_ROOT"]?.trim();
	const pluginData = options.env["PLUGIN_DATA"]?.trim();
	if (pluginRoot === undefined || pluginRoot.length === 0 || pluginData === undefined || pluginData.length === 0) {
		return { action: "skip-missing-env", exitCode: 0 };
	}

	const pluginVersion = await readPluginVersion(pluginRoot);
	if (pluginVersion === undefined) return { action: "skip-version-unresolved", exitCode: 0 };

	const state = await readBootstrapState(resolveBootstrapStatePath(pluginData));
	if (state.completedForVersion === pluginVersion) return { action: "skip-completed", exitCode: 0 };

	if (await isLockFresh(resolveBootstrapLockPath(pluginData), now)) return { action: "skip-locked", exitCode: 0 };

	const spawnWorker = options.spawnWorker ?? spawnDetachedWorker;
	spawnWorker({
		args: [options.workerCliPath ?? defaultWorkerCliPath(), "worker"],
		command: process.execPath,
		env: options.env,
	});
	const writeNotice = options.writeNotice ?? ((line: string) => process.stdout.write(`${line}\n`));
	writeNotice(
		JSON.stringify({
			hookSpecificOutput: {
				hookEventName: "SessionStart",
				additionalContext: BOOTSTRAP_RESTART_NOTICE,
			},
		}),
	);
	return { action: "spawned", exitCode: 0 };
}

function spawnDetachedWorker(invocation: WorkerSpawnInvocation): void {
	const child = spawn(invocation.command, [...invocation.args], {
		detached: true,
		env: invocation.env,
		stdio: "ignore",
	});
	child.unref();
}

function defaultWorkerCliPath(): string {
	// In the esbuild bundle every module shares import.meta.url, so this
	// resolves to dist/cli.js — the file the detached worker must re-enter.
	return fileURLToPath(import.meta.url);
}

async function isLockFresh(lockPath: string, now: number): Promise<boolean> {
	try {
		const lockStat = await stat(lockPath);
		return now - lockStat.mtimeMs < DEFAULT_LOCK_STALE_MS;
	} catch {
		return false;
	}
}

async function drainStdin(stdin: NonNullable<SessionStartHookOptions["stdin"]>): Promise<void> {
	if (stdin.isTTY === true) return;
	for await (const chunk of stdin) {
		void chunk;
	}
}

