function applyPatchEvent(details: unknown, overrides: Partial<ToolResultLike> = {}): ToolResultLike {
	return {
		toolName: "apply_patch",
		input: {
			command: [
				"*** Begin Patch",
				"*** Update File: src/raw.ts",
				"@@",
				"-const raw = false;",
				"+const raw = true;",
				"*** End Patch",
			].join("\n"),
		},
		...(details === undefined ? {} : { details }),
		...overrides,
	};
}

