			env: {},
			platform: "darwin",
			pluginDataRoot,
		});

		// then
		expect(output).toBe("");
	});

	it("#given non-Bash tool call #when hook runs #then it stays silent", () => {
		// given
		const pluginDataRoot = createTemporaryDirectory("omo-git-bash-hook-");

		// when
		const output = applyGitBashPreToolUseReminder(preToolPayload("exec_command"), {
