			}
		},
	});
}

import { mkdirSync, rmSync } from "node:fs";
import { dirname } from "node:path";

export const SESSION_STATE_LOCK_CONTENDED = Symbol("session-state-lock-contended");

export type SessionStateLockResult<T> = T | typeof SESSION_STATE_LOCK_CONTENDED;

const LOCK_RETRY_COUNT = 20;
const LOCK_RETRY_DELAY_MS = 5;
const LOCK_SLEEP_VIEW = new Int32Array(new SharedArrayBuffer(4));

export function withSessionStateLock<T>(cachePath: string, callback: () => T): SessionStateLockResult<T> {
	const lockPath = `${cachePath}.lock`;
	mkdirSync(dirname(cachePath), { recursive: true });
	for (let attempt = 0; attempt < LOCK_RETRY_COUNT; attempt += 1) {
		try {
			mkdirSync(lockPath);
			try {
				return callback();
			} finally {
				rmSync(lockPath, { recursive: true, force: true });
			}
		} catch (error) {
			if (errorCode(error) === "EEXIST") {
				sleepSync(LOCK_RETRY_DELAY_MS);
				continue;
			}
			throw error;
		}
	}
	return SESSION_STATE_LOCK_CONTENDED;
}

function errorCode(error: unknown): unknown {
	if (!isRecord(error)) {
		return undefined;
	}
	return Reflect.get(error, "code");
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function sleepSync(milliseconds: number): void {
	Atomics.wait(LOCK_SLEEP_VIEW, 0, 0, milliseconds);
}

import { existsSync } from "node:fs";
import { join } from "node:path";

type RuntimeEnv = Readonly<Record<string, string | undefined>>;

interface OmoResolutionDeps {
	readonly fileExists?: (path: string) => boolean;
	readonly platform?: NodeJS.Platform;
}

const SPARKSHELL_AWARENESS_MARKER = "## Sparkshell Runtime";

export const SPARKSHELL_AWARENESS_DEDUP_KEY = "__omo_sparkshell_awareness__";

export function isCodexAppServerActive(env: RuntimeEnv = process.env): boolean {
	const originator = env["CODEX_INTERNAL_ORIGINATOR_OVERRIDE"]?.toLowerCase() ?? "";
	const bundleIdentifier = env["__CFBundleIdentifier"]?.toLowerCase() ?? "";
	const shellActive = isTruthy(env["CODEX_SHELL"]);

	return (
		shellActive &&
		(originator.includes("codex desktop") ||
			originator.includes("codex app") ||
			bundleIdentifier === "com.openai.codex")
	);
}

function isSparkShellAppServerConfigured(env: RuntimeEnv = process.env): boolean {
	const codexSocketPath = env["CODEX_APP_SERVER_SOCKET"]?.trim() ?? "";
	const omoSocketPath = env["OMO_SPARKSHELL_APP_SERVER_SOCKET"]?.trim() ?? "";
	return codexSocketPath.length > 0 || omoSocketPath.length > 0;
}

export function resolveOmoInvocation(env: RuntimeEnv = process.env, deps: OmoResolutionDeps = {}): string | null {
	const fileExists = deps.fileExists ?? existsSync;
	const platform = deps.platform ?? process.platform;
	const binNames = platform === "win32" ? ["omo.cmd", "omo.exe", "omo"] : ["omo"];
	const pathDelimiter = platform === "win32" ? ";" : ":";
	const pathEntries = (env["PATH"] ?? "").split(pathDelimiter).filter((entry) => entry.trim().length > 0);
	for (const pathEntry of pathEntries) {
		for (const binName of binNames) {
			if (fileExists(join(pathEntry, binName))) return "omo";
		}
	}
	for (const candidateDir of omoCandidateBinDirs(env)) {
		for (const binName of binNames) {
			const candidate = join(candidateDir, binName);
			if (fileExists(candidate)) return candidate;
		}
	}
	return null;
}

function omoCandidateBinDirs(env: RuntimeEnv): readonly string[] {
	const dirs: string[] = [];
	const localBinDir = env["CODEX_LOCAL_BIN_DIR"]?.trim() ?? "";
	if (localBinDir.length > 0) dirs.push(localBinDir);
	const home = env["HOME"]?.trim() || env["USERPROFILE"]?.trim() || "";
	const codexHome = env["CODEX_HOME"]?.trim() || (home.length > 0 ? join(home, ".codex") : "");
	if (codexHome.length > 0) dirs.push(join(codexHome, "bin"));
	if (home.length > 0) dirs.push(join(home, ".local", "bin"));
	return dirs;
}

export function getSparkShellRuntimeAwareness(env: RuntimeEnv = process.env, deps: OmoResolutionDeps = {}): string {
	const override = env["OMO_SPARKSHELL_AWARENESS"] ?? env["LAZYCODEX_SPARKSHELL_AWARENESS"];
	if (isFalsy(override)) {
		return "";
	}
	if (!isTruthy(override) && !isCodexAppServerActive(env) && !isSparkShellAppServerConfigured(env)) {
		return "";
	}

	const resolved = resolveOmoInvocation(env, deps);
	const invocation = resolved ?? (isTruthy(override) ? "omo" : null);
	if (invocation === null) {
		return "";
	}
	const command = /\s/.test(invocation) ? `"${invocation}"` : invocation;

	return [
		SPARKSHELL_AWARENESS_MARKER,
		"",
		`- Use \`${command} sparkshell <command> [args...]\` first for repo inspection, CLI smoke tests, git/history checks, and bounded command output. Pass ordinary commands as executable and arguments in separate argv tokens, for example \`${command} sparkshell rg --files\`; not \`${command} sparkshell 'rg --files'\`, because the quoted string is treated as one executable name. Raw \`rg\`/\`grep\`/\`cat\`/\`git\` are fallbacks when Sparkshell is unavailable or too narrow for the task.`,
		`- Use \`${command} sparkshell --shell '<command>'\` only for shell syntax such as metacharacters, pipelines, redirects, command substitution, or variable expansion.`,
		`- Use \`${command} sparkshell --tmux-pane <pane-id> --tail-lines 400\` only to inspect an existing pane, never to launch ordinary commands. Tail lines must stay between 100 and 1000.`,
		"- When no native sidecar or appserver is available, Sparkshell silently falls back to raw command execution. `OMO_SPARKSHELL_BIN` selects a native sidecar path.",
		"- When `CODEX_THREAD_ID` identifies a Codex session, Sparkshell feeds recent session context (first/latest user request + last 5 conversation messages) into oversized-output condensation for relevance ranking, but never appends that context to command output. `OMO_SPARKSHELL_SESSION_CONTEXT=0` disables the lookup.",
		`- Route potentially huge output (full log files, big diffs, \`cat\`/\`grep\` over large artifacts) through \`${command} sparkshell\` instead of reading it raw: oversized output is condensed to a budget while preserving error signatures, repeated patterns, session-goal-relevant lines, and head/tail. Tune with \`--budget <chars>\`; disable with \`OMO_SPARKSHELL_CONDENSE=0\`.`,
		"- Oversized output is first summarized by the spark model (`codex exec`, default `gpt-5.3-codex-spark`) fed with the shell output plus session context: the summary keeps selected output as-is (no masking) and ends with a `[sparkshell caption]` line describing what ran, what the full output contained, and which lines were omitted. `OMO_SPARKSHELL_SPARK=0` skips the model and uses deterministic condensation directly.",
	].join("\n");
}

function isTruthy(value: string | undefined): boolean {
	if (value === undefined) {
		return false;
	}
	return ["1", "true", "yes", "on"].includes(value.trim().toLowerCase());
}

function isFalsy(value: string | undefined): boolean {
	if (value === undefined) {
		return false;
	}
	return ["0", "false", "no", "off"].includes(value.trim().toLowerCase());
}

import { existsSync } from "node:fs";

import type { CodexRulesHookOptions } from "./codex-hook-options.js";
import { configFromEnvironment } from "./config.js";
import { withPromptBudget } from "./event-budget.js";
import { formatAdditionalContextOutput } from "./hook-output.js";
import { completePostCompactRecovery, hydrateEngineState, persistEngineState } from "./persistent-cache.js";
import { withPostCompactBudget } from "./post-compact-budget.js";
import { buildPostCompactReadDirective } from "./post-compact-directive.js";
import type { Engine } from "@oh-my-opencode/rules-engine/engine";
import { isNeverTruncatedRule } from "@oh-my-opencode/rules-engine/engine";
import type { LoadedRule, PiRulesConfig } from "@oh-my-opencode/rules-engine/engine";
import { createRulesEngine } from "./rules-engine-factory.js";
import { getSparkShellRuntimeAwareness, SPARKSHELL_AWARENESS_DEDUP_KEY } from "./sparkshell-awareness.js";
import { filterRulesAlreadyInTranscript, filterRulesNotInTranscriptText } from "./transcript-rule-filter.js";
import type { TranscriptSearchOptions } from "./transcript-search.js";
import { readTranscriptSearchText } from "./transcript-search.js";

export function runStaticInjection(
	cwd: string,
	transcriptPath: string | null,
	eventName: "SessionStart" | "UserPromptSubmit",
	cachePath: string,
	options: CodexRulesHookOptions,
	completedPostCompactChannel?: "static",
	transcriptSearchOptions: TranscriptSearchOptions = {},
	model?: string,
): string {
	const config = configFromEnvironment(options.env);
	if (config.disabled || config.mode === "off" || config.mode === "dynamic") {
		if (completedPostCompactChannel !== undefined) {
			completePostCompactRecovery(cachePath, completedPostCompactChannel);
		}
		return "";
	}

	if (completedPostCompactChannel !== undefined) {
		return runPostCompactRecovery({
			cwd,
			transcriptPath,
			eventName,
			cachePath,
			options,
			channel: completedPostCompactChannel,
			model: model ?? "",
			config,
		});
	}

	const effectiveConfig = eventName === "UserPromptSubmit" ? withPromptBudget(config) : config;
	const engine = createRulesEngine(options, effectiveConfig);
	hydrateEngineState(engine, cachePath);
	engine.state.cwd = cwd;

	const loaded = engine.loadStaticRules(cwd);
	const rules = filterRulesAlreadyInTranscript(
		loaded.rules.filter((rule) => !engine.isStaticInjected(rule)),
		transcriptPath,
		(rule) => {
			engine.markStaticInjected(rule);
		},
		transcriptSearchOptions,
	);
	const sparkshellAwareness = engine.state.staticDedup.has(SPARKSHELL_AWARENESS_DEDUP_KEY)
		? ""
		: getSparkShellRuntimeAwareness(options.env);
	if (rules.length === 0 && sparkshellAwareness.length === 0) {
		persistEngineState(engine, cachePath);
		return "";
	}

	const block = engine.formatStatic(rules);
	for (const rule of rules) {
		engine.markStaticInjected(rule);
	}
	if (sparkshellAwareness.length > 0) {
		engine.state.staticDedup.add(SPARKSHELL_AWARENESS_DEDUP_KEY);
	}
	persistEngineState(engine, cachePath);
	return formatAdditionalContextOutput(eventName, combineStaticContext(block, sparkshellAwareness));
}

interface PostCompactRecoveryInput {
	cwd: string;
	transcriptPath: string | null;
	eventName: "SessionStart" | "UserPromptSubmit";
	cachePath: string;
	options: CodexRulesHookOptions;
	channel: "static";
	model: string;
	config: PiRulesConfig;
}

function runPostCompactRecovery(input: PostCompactRecoveryInput): string {
	const effectiveConfig = withPostCompactBudget(input.config, {
		model: input.model,
		transcriptPath: input.transcriptPath,
	});
	const engine = createRulesEngine(input.options, effectiveConfig);
	hydrateEngineState(engine, input.cachePath);
	engine.state.cwd = input.cwd;

	const loaded = engine.loadStaticRules(input.cwd);
	const transcriptText = readRecoveryTranscriptText(input.transcriptPath);
	const missingRules = filterRulesNotInTranscriptText(
		loaded.rules.filter((rule) => !engine.isStaticInjected(rule)),
		transcriptText,
		(rule) => {
			engine.markStaticInjected(rule);
		},
	);
	const dynamicRulePaths = recoverDynamicRulePaths(engine, transcriptText, loaded.rules);
	const sparkshellAwareness = engine.state.staticDedup.has(SPARKSHELL_AWARENESS_DEDUP_KEY)
		? ""
		: getSparkShellRuntimeAwareness(input.options.env);

	if (missingRules.length === 0 && dynamicRulePaths.length === 0 && sparkshellAwareness.length === 0) {
		persistEngineState(engine, input.cachePath, input.channel);
		return "";
	}

	const fullBodyRules = missingRules.filter((rule) => isNeverTruncatedRule(ruleDisplayPath(rule)));
	const listedRules = missingRules.filter((rule) => !isNeverTruncatedRule(ruleDisplayPath(rule)));
	const bodyBlock = fullBodyRules.length === 0 ? "" : engine.formatStatic(fullBodyRules);
	const directive = buildPostCompactReadDirective(
		[...listedRules.map((rule) => rule.path), ...dynamicRulePaths],
		effectiveConfig.maxResultChars,
	);
	for (const rule of missingRules) {
		engine.markStaticInjected(rule);
	}
	if (sparkshellAwareness.length > 0) {
		engine.state.staticDedup.add(SPARKSHELL_AWARENESS_DEDUP_KEY);
	}
	persistEngineState(engine, input.cachePath, input.channel);
	return formatAdditionalContextOutput(
		input.eventName,
		combineStaticContext(bodyBlock, directive, sparkshellAwareness),
	);
}

function readRecoveryTranscriptText(transcriptPath: string | null): string | null {
	if (transcriptPath === null) {
		return null;
	}
	return (
		readTranscriptSearchText(transcriptPath, { latestCompactedReplacementOnly: true }) ??
		readTranscriptSearchText(transcriptPath)
	);
}

function recoverDynamicRulePaths(
	engine: Engine,
	transcriptText: string | null,
	staticRules: ReadonlyArray<LoadedRule>,
): string[] {
	const staticRulePaths = new Set(staticRules.map((rule) => rule.realPath));
	const recoveredPaths = new Set<string>();
	for (const dedupKeys of engine.state.dynamicDedup.values()) {
		for (const dedupKey of dedupKeys) {
			const separatorIndex = dedupKey.lastIndexOf("::");
			if (separatorIndex <= 0) {
				continue;
			}
			const rulePath = dedupKey.slice(0, separatorIndex);
			if (staticRulePaths.has(rulePath)) {
				continue;
			}
			if (transcriptText !== null && transcriptText.includes(rulePath)) {
				continue;
			}
			if (!existsSync(rulePath)) {
				continue;
			}
			recoveredPaths.add(rulePath);
		}
	}
	return [...recoveredPaths].sort();
}

function ruleDisplayPath(rule: LoadedRule): string {
	return rule.relativePath.length > 0 ? rule.relativePath : rule.path;
}

function combineStaticContext(...blocks: readonly string[]): string {
	return blocks.filter((block) => block.trim().length > 0).join("\n\n");
}

import { existsSync, statSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";

export interface CodexPostToolUseLike {
	tool_name: string;
	tool_input: unknown;
	tool_response: unknown;
}

const COMMAND_TOOL_NAMES = new Set(["bash", "shell_command", "exec_command"]);
const TRACKED_TOOL_NAMES = new Set([
	"read",
	"read_file",
	"mcp__filesystem__read_file",
	"mcp__filesystem__read_multiple_files",
	"mcp__filesystem__write_file",
	"mcp__filesystem__edit_file",
	"write",
	"edit",
	"multiedit",
	"multi_edit",
	"apply_patch",
	"bash",
	"shell_command",
	"exec_command",
]);

export function extractCodexToolPaths(input: CodexPostToolUseLike, cwd: string): string[] {
	const toolName = input.tool_name.toLowerCase();
	if (!TRACKED_TOOL_NAMES.has(toolName) || isFailedToolResponse(input.tool_response)) {
		return [];
	}

	const paths = new Set<string>();
	const toolInput = isRecord(input.tool_input) ? input.tool_input : {};
	addCommonPathFields(paths, toolInput, cwd);
	addPatchPayloadPaths(paths, toolInput, cwd);
	addPatchRecordPaths(paths, toolInput["files"], cwd);
	addPatchRecordPaths(paths, toolInput["changes"], cwd);

	if (COMMAND_TOOL_NAMES.has(toolName)) {
		const command = stringProperty(toolInput, "command") ?? stringProperty(toolInput, "cmd");
		const workdir = stringProperty(toolInput, "workdir") ?? stringProperty(toolInput, "cwd");
		addCommandPaths(paths, command, workdir === undefined ? cwd : resolvePath(cwd, workdir));
	}

	return [...paths];
}

function addCommonPathFields(paths: Set<string>, input: Record<string, unknown>, cwd: string): void {
	for (const key of ["path", "filePath", "file_path", "target", "targetPath", "target_path"]) {
		addPath(paths, input[key], cwd, false);
	}
	for (const key of ["paths", "filePaths", "file_paths"]) {
		addPathArray(paths, input[key], cwd, false);
	}
}

function addPatchPayloadPaths(paths: Set<string>, input: Record<string, unknown>, cwd: string): void {
	for (const key of ["input", "patch", "command", "cmd"]) {
		const value = input[key];
		if (typeof value === "string") {
			addPatchHeaderPaths(paths, value, cwd);
		}
	}
}

function addPatchHeaderPaths(paths: Set<string>, patch: string, cwd: string): void {
	for (const line of patch.split("\n")) {
		for (const prefix of ["*** Add File: ", "*** Update File: ", "*** Move to: "]) {
			if (line.startsWith(prefix)) {
				addPath(paths, line.slice(prefix.length).trim(), cwd, false);
			}
		}
	}
}

function addPatchRecordPaths(paths: Set<string>, value: unknown, cwd: string): void {
	if (!Array.isArray(value)) return;
	for (const item of value) {
		if (typeof item === "string") {
			addPath(paths, item, cwd, false);
			continue;
		}
		if (!isRecord(item)) continue;
		addCommonPathFields(paths, item, cwd);
		for (const key of ["movePath", "move_path", "to", "from"]) {
			addPath(paths, item[key], cwd, false);
		}
	}
}

function addCommandPaths(paths: Set<string>, command: string | undefined, cwd: string): void {
	if (command === undefined) return;
	for (const token of tokenizeShell(command)) {
		if (token.length === 0 || token.startsWith("-") || token.includes("*")) {
			continue;
		}
		addPath(paths, token, cwd, true);
	}
}

function addPathArray(paths: Set<string>, value: unknown, cwd: string, mustExist: boolean): void {
	if (!Array.isArray(value)) return;
	for (const item of value) {
		addPath(paths, item, cwd, mustExist);
	}
}

function addPath(paths: Set<string>, value: unknown, cwd: string, mustExist: boolean): void {
	if (typeof value !== "string" || value.length === 0 || looksLikeUrl(value)) {
		return;
	}

	const path = resolvePath(cwd, value);
	if (mustExist && !isExistingFile(path)) {
		return;
	}
	paths.add(path);
}

function resolvePath(cwd: string, filePath: string): string {
	return isAbsolute(filePath) ? filePath : resolve(cwd, filePath);
}

function isExistingFile(filePath: string): boolean {
	try {
		return existsSync(filePath) && statSync(filePath).isFile();
	} catch {
		return false;
	}
}

function looksLikeUrl(value: string): boolean {
	return /^[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(value);
}

function stringProperty(value: Record<string, unknown>, key: string): string | undefined {
	const property = value[key];
	return typeof property === "string" && property.length > 0 ? property : undefined;
}

function tokenizeShell(command: string): string[] {
	const tokens: string[] = [];
	let current = "";
	let quote: "'" | '"' | null = null;
	let escaped = false;

	for (const character of command) {
		if (escaped) {
			current += character;
			escaped = false;
			continue;
		}
		if (character === "\\") {
			escaped = true;
			continue;
		}
		if ((character === "'" || character === '"') && quote === null) {
			quote = character;
			continue;
		}
		if (quote === character) {
			quote = null;
			continue;
		}
		if (quote === null && /\s/.test(character)) {
			if (current.length > 0) {
				tokens.push(current);
				current = "";
			}
			continue;
		}
		current += character;
	}

	if (current.length > 0) {
		tokens.push(current);
	}
	return tokens;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isFailedToolResponse(value: unknown): boolean {
	if (!isRecord(value)) return false;
	return (
		value["isError"] === true || value["is_error"] === true || value["error"] === true || value["status"] === "error"
	);
}

import type { LoadedRule } from "@oh-my-opencode/rules-engine/engine";
import type { TranscriptSearchOptions } from "./transcript-search.js";
import { readTranscriptSearchText } from "./transcript-search.js";

export function filterRulesAlreadyInTranscript(
	rules: ReadonlyArray<LoadedRule>,
	transcriptPath: string | null,
	markInjected: (rule: LoadedRule) => void,
	options: TranscriptSearchOptions = {},
): LoadedRule[] {
	if (rules.length === 0 || transcriptPath === null) {
		return [...rules];
	}

	const transcriptText = readTranscriptSearchText(transcriptPath, options);
	return filterRulesNotInTranscriptText(rules, transcriptText, markInjected);
}

export function filterRulesNotInTranscriptText(
	rules: ReadonlyArray<LoadedRule>,
	transcriptText: string | null,
	markInjected: (rule: LoadedRule) => void,
): LoadedRule[] {
	if (rules.length === 0 || transcriptText === null) {
		return [...rules];
	}

	const pendingRules: LoadedRule[] = [];
	for (const rule of rules) {
		if (isRuleAlreadyInTranscript(rule, transcriptText)) {
			markInjected(rule);
			continue;
		}

		pendingRules.push(rule);
	}
	return pendingRules;
}

function isRuleAlreadyInTranscript(rule: LoadedRule, transcriptText: string): boolean {
	const staticReferenceNeedles = [
		`- [${displayFilename(rule)}]{${rule.path}}`,
		`- [${displayFilename(rule)}]{${rule.realPath}}`,
	];
	if (staticReferenceNeedles.some((needle) => transcriptText.includes(needle))) {
		return true;
	}

	const bodyNeedle = rule.body.trim().slice(0, 2_000);
	if (bodyNeedle.length === 0 || !transcriptText.includes(bodyNeedle)) {
		return false;
	}

	const markers = [
		`Instructions from: ${rule.path}`,
		`Instructions from: ${rule.realPath}`,
		rule.relativePath.length === 0 ? null : rule.relativePath,
	].filter((marker): marker is string => marker !== null);
	return markers.some((marker) => transcriptText.includes(marker));
}

function displayFilename(rule: LoadedRule): string {
	const normalizedPath = rule.relativePath.length > 0 ? rule.relativePath : rule.path;
	const segments = normalizedPath
		.replace(/\\/g, "/")
		.split("/")
		.filter((segment) => segment.length > 0);
	return segments.at(-1) ?? normalizedPath;
}

import { readFileSync } from "node:fs";

export interface TranscriptSearchOptions {
	readonly latestCompactedReplacementOnly?: boolean;
}

export function readTranscriptSearchText(transcriptPath: string, options: TranscriptSearchOptions = {}): string | null {
	try {
		const rawTranscript = readFileSync(transcriptPath, "utf8");
		if (options.latestCompactedReplacementOnly === true) {
			return latestCompactedReplacementSearchText(rawTranscript);
		}
		return [rawTranscript, ...collectJsonLineStrings(rawTranscript)].join("\n");
	} catch (error) {
		if (!(error instanceof Error)) {
			throw error;
		}
		return null;
	}
}

function latestCompactedReplacementSearchText(rawTranscript: string): string | null {
	const lines = rawTranscript.split(/\r?\n/);
	let latestCompactedLineIndex = -1;
	let replacementHistory: unknown[] | null = null;
	for (const [index, line] of lines.entries()) {
		const parsed = parseJsonLine(line);
		if (!isRecord(parsed) || parsed["type"] !== "compacted") {
			continue;
		}

		const payload = parsed["payload"];
		if (!isRecord(payload)) {
			continue;
		}

		const candidateReplacementHistory = payload["replacement_history"];
		if (!Array.isArray(candidateReplacementHistory)) {
			continue;
		}

		latestCompactedLineIndex = index;
		replacementHistory = candidateReplacementHistory;
	}

	if (replacementHistory === null) {
		return null;
	}

	const values: string[] = [];
	collectStrings(replacementHistory, values);
	const laterTranscript = lines.slice(latestCompactedLineIndex + 1).join("\n");
	values.push(laterTranscript, ...collectJsonLineStrings(laterTranscript));
	return values.join("\n");
}

function collectJsonLineStrings(rawTranscript: string): string[] {
	const values: string[] = [];
	for (const line of rawTranscript.split(/\r?\n/)) {
		const parsed = parseJsonLine(line);
		if (parsed !== null) {
			collectStrings(parsed, values);
		}
	}
	return values;
}

function parseJsonLine(line: string): unknown | null {
	if (line.trim().length === 0) {
		return null;
	}

	try {
		const parsed: unknown = JSON.parse(line);
		return parsed;
	} catch (error) {
		if (!(error instanceof Error)) {
			throw error;
		}
		return null;
	}
}

function collectStrings(value: unknown, output: string[]): void {
	if (typeof value === "string") {
		output.push(value);
		return;
	}

	if (Array.isArray(value)) {
		for (const item of value) {
			collectStrings(item, output);
		}
		return;
	}

	if (!isRecord(value)) {
		return;
	}

	for (const item of Object.values(value)) {
		collectStrings(item, output);
	}
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
