import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { fingerprintDynamicTargets } from "../src/dynamic-target-fingerprints.js";
import { defaultConfig } from "@oh-my-opencode/rules-engine/engine";

const tempDirectories: string[] = [];

afterEach(() => {
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
});

describe("codex rules dynamic target fingerprints", () => {
	it("#given auto source mode #when an excluded source file changes #then cache key stays stable", () => {
		// given
		const { cwd, targetPath } = makeProjectWithDefaultSources();
		const config = defaultConfig();

		// when
		const initial = fingerprintDynamicTargets(cwd, [targetPath], config);
		writeFileSync(
			path.join(cwd, "AGENTS.md"),
			[
				"Always use the exact code style.",
				"Updated guidance.",
				"",
				"This file should be excluded from auto mode.",
			].join("\n"),
		);
		const afterChange = fingerprintDynamicTargets(cwd, [targetPath], config);
		writeFileSync(
			path.join(cwd, ".github", "instructions", "workflow.md"),
			["---", "description: Workflow rules", 'globs: ["**/*.ts"]', "---", "Prefer explicit return types."].join(
				"\n",
			),
		);
		const afterEnabledChange = fingerprintDynamicTargets(cwd, [targetPath], config);
		const initialFingerprint = initial[0]?.fingerprint;

		// then
		expect(afterChange).toHaveLength(1);
		expect(afterEnabledChange).toHaveLength(1);
		expect(initialFingerprint).toBeDefined();
		expect(afterChange[0]?.fingerprint).toBe(initialFingerprint);
		expect(afterEnabledChange[0]?.fingerprint).not.toBe(initialFingerprint);
	});
});

function makeProjectWithDefaultSources(): { cwd: string; targetPath: string } {
	const root = mkdtempSync(path.join(tmpdir(), "codex-rules-fingerprint-"));
	const projectRoot = path.join(root, "repo");
	const instructionPath = path.join(projectRoot, ".github", "instructions");
	const targetPath = path.join(projectRoot, "src", "app.ts");
	tempDirectories.push(root);

	mkdirSync(instructionPath, { recursive: true });
	mkdirSync(path.dirname(targetPath), { recursive: true });
	writeFileSync(path.join(projectRoot, "package.json"), "{}");
	writeFileSync(path.join(projectRoot, "AGENTS.md"), "Default project AGENTS file.");
	writeFileSync(path.join(projectRoot, ".github", "copilot-instructions.md"), "Legacy copilot instruction");
	writeFileSync(
		path.join(instructionPath, "workflow.md"),
		["---", "description: Workflow rules", 'globs: ["**/*.ts"]', "---", "Keep async/await explicit."].join("\n"),
	);
	writeFileSync(targetPath, "export const answer = 42;\n");
	return { cwd: projectRoot, targetPath };
}

import { join } from "node:path";
import { describe, expect, it } from "vitest";

import { configFromEnvironment } from "../src/config.js";
import { createEngine, defaultConfig, type EngineDeps } from "@oh-my-opencode/rules-engine/engine";
import { matchRule as defaultMatchRule } from "@oh-my-opencode/rules-engine/engine";
import type { RuleCandidate } from "@oh-my-opencode/rules-engine/engine";

const projectRoot = "/tmp/codex-rules-engine";

function makeCandidate(overrides: Partial<RuleCandidate> = {}): RuleCandidate {
	const candidate = {
		path: join(projectRoot, ".omo", "rules", "typescript.md"),
		realPath: join(projectRoot, ".omo", "rules", "typescript.md"),
		source: ".omo/rules",
		distance: 0,
		isGlobal: false,
		isSingleFile: false,
		relativePath: ".omo/rules/typescript.md",
	} satisfies RuleCandidate;
	return { ...candidate, ...overrides };
}

describe("rule engine dynamic matching", () => {
	it("#given duplicate target paths #when loading dynamic rules #then repeated discovery and parsing work is avoided", () => {
		// given
		const targetPath = join(projectRoot, "src", "app.ts");
		const candidate = makeCandidate();
		const counters = {
			findProjectRoot: 0,
			findCandidates: 0,
			readFile: 0,
		};
		const deps = {
			findProjectRoot: () => {
				counters.findProjectRoot += 1;
				return projectRoot;
			},
			findCandidates: () => {
				counters.findCandidates += 1;
				return [candidate];
			},
			readFile: () => {
				counters.readFile += 1;
				return ["---", "globs: **/*.ts", "---", "", "Prefer strict TypeScript."].join("\n");
			},
		} satisfies EngineDeps;
		const engine = createEngine(defaultConfig(), deps);

		// when
		const result = engine.loadDynamicRules(projectRoot, [targetPath, targetPath, targetPath]);

		// then
		expect(result.rules).toHaveLength(1);
		expect(counters).toEqual({
			findProjectRoot: 1,
			findCandidates: 1,
			readFile: 1,
		});
	});

	it("#given distinct target files in same directory #when loading dynamic rules #then candidate discovery is reused", () => {
		// given
		const firstTarget = join(projectRoot, "src", "first.ts");
		const secondTarget = join(projectRoot, "src", "second.ts");
		const thirdTarget = join(projectRoot, "src", "third.ts");
		const candidate = makeCandidate();
		let findCandidatesCalls = 0;
		const deps = {
			findProjectRoot: () => projectRoot,
			findCandidates: () => {
				findCandidatesCalls += 1;
				return [candidate];
			},
			readFile: () => ["---", "globs: **/*.ts", "---", "", "Prefer strict TypeScript."].join("\n"),
		} satisfies EngineDeps;
		const engine = createEngine(defaultConfig(), deps);

		// when
		const result = engine.loadDynamicRules(projectRoot, [firstTarget, secondTarget, thirdTarget]);

		// then
		expect(result.rules).toHaveLength(1);
		expect(findCandidatesCalls).toBe(1);
	});

	it("#given same rule content and target across loads #when loading dynamic rules repeats #then cached match decision is reused", () => {
		// given
		const targetPath = join(projectRoot, "src", "app.ts");
		const candidate = makeCandidate();
		let matchCalls = 0;
		const deps = {
			findProjectRoot: () => projectRoot,
			findCandidates: () => [candidate],
			readFile: () => ["---", "globs: **/*.ts", "---", "", "Prefer strict TypeScript."].join("\n"),
			matchRule: (input) => {
				matchCalls += 1;
				return defaultMatchRule(input);
			},
		} satisfies EngineDeps;
		const engine = createEngine(defaultConfig(), deps);

		// when
		const firstResult = engine.loadDynamicRules(projectRoot, [targetPath]);
		const secondResult = engine.loadDynamicRules(projectRoot, [targetPath]);

		// then
		expect(firstResult.rules).toHaveLength(1);
		expect(secondResult.rules).toHaveLength(1);
		expect(matchCalls).toBe(1);
	});

	it("#given same rule path changes body #when loading dynamic rules repeats #then cached match decision invalidates", () => {
		// given
		const targetPath = join(projectRoot, "src", "app.ts");
		const candidate = makeCandidate();
		let body = "Prefer strict TypeScript.";
		let matchCalls = 0;
		const deps = {
			findProjectRoot: () => projectRoot,
			findCandidates: () => [candidate],
			readFile: () => ["---", "globs: **/*.ts", "---", "", body].join("\n"),
			matchRule: (input) => {
				matchCalls += 1;
				return defaultMatchRule(input);
			},
		} satisfies EngineDeps;
		const engine = createEngine(defaultConfig(), deps);

		// when
		engine.loadDynamicRules(projectRoot, [targetPath]);
		body = "Prefer readonly TypeScript.";
		engine.loadDynamicRules(projectRoot, [targetPath]);

		// then
		expect(matchCalls).toBe(2);
	});

	it("#given same rule path changes frontmatter #when loading dynamic rules repeats #then cached match decision invalidates", () => {
		// given
		const targetPath = join(projectRoot, "src", "app.ts");
		const candidate = makeCandidate();
		let globs = "**/*.ts";
		let matchCalls = 0;
		const deps = {
			findProjectRoot: () => projectRoot,
			findCandidates: () => [candidate],
			readFile: () => ["---", `globs: ${globs}`, "---", "", "Prefer strict TypeScript."].join("\n"),
			matchRule: (input) => {
				matchCalls += 1;
				return defaultMatchRule(input);
			},
		} satisfies EngineDeps;
		const engine = createEngine(defaultConfig(), deps);

		// when
		const firstResult = engine.loadDynamicRules(projectRoot, [targetPath]);
		globs = "**/*.tsx";
		const secondResult = engine.loadDynamicRules(projectRoot, [targetPath]);

