export function writeCompactedTranscript(root: string, retainedText: string): string {
	const transcriptPath = path.join(root, "transcript-compacted.jsonl");
	writeFileSync(
		transcriptPath,
		`${JSON.stringify({
			type: "compacted",
			payload: {
				message: "summary",
				replacement_history: [{ type: "message", role: "user", content: retainedText }],
			},
		})}\n`,
	);
	return transcriptPath;
}

export function writeCompactedWarningTranscript(root: string, retainedText: string): string {
	const transcriptPath = path.join(root, "transcript-compacted-warning.jsonl");
	writeFileSync(
		transcriptPath,
		[
			JSON.stringify({
				type: "message",
				payload: {
					content: "Skill descriptions were shortened to fit the 2% skills context budget. Context compacted.",
				},
			}),
			JSON.stringify({
				type: "compacted",
				payload: {
					message: "summary",
					replacement_history: [{ type: "message", role: "user", content: retainedText }],
				},
			}),
			JSON.stringify({
				type: "message",
				payload: {
					content: "Your input exceeds the context window of this model. Please adjust your input and try again.",
				},
			}),
			"",
		].join("\n"),
	);
	return transcriptPath;
}

export function writeMalformedContextTooLargeTranscript(root: string, retainedText = ""): string {
	const transcriptPath = path.join(root, "transcript-context-too-large.jsonl");
	writeFileSync(
		transcriptPath,
		[
			"{not json",
			retainedText,
			JSON.stringify({
				type: "message",
				payload: {
					content: "Skill descriptions were shortened to fit the 2% skills context budget. Context compacted.",
				},
			}),
			JSON.stringify({
				type: "message",
				payload: {
					content: {
						error: {
							code: "context_too_large",
							message:
								"Your input exceeds the context window of this model. Please adjust your input and try again.",
						},
					},
				},
			}),
			"",
		].join("\n"),
	);
	return transcriptPath;
}

export function readOptionalAdditionalContext(output: string): string {
	if (output.trim().length === 0) {
		return "";
	}
	return readAdditionalContext(output);
}

export function readAdditionalContext(output: string): string {
	if (output.trim().length === 0) {
		throw new Error("Expected hook output to include additional context.");
	}
	const parsed: unknown = JSON.parse(output);
	if (!isRecord(parsed)) return "";
	const hookSpecificOutput = parsed["hookSpecificOutput"];
	if (!isRecord(hookSpecificOutput)) return "";
	const additionalContext = hookSpecificOutput["additionalContext"];
	return typeof additionalContext === "string" ? additionalContext : "";
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import {
	findPluginBundledCandidates,
	matchRule,
	parseRule,
	scanRuleFiles,
	SOURCE_PRIORITY,
} from "@oh-my-opencode/rules-engine/engine";

const tempDirectories: string[] = [];

afterEach(() => {
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
});

describe("rules-engine package consumption", () => {
	it("#given Codex bundled rule sources #when imported from rules-engine #then plugin-bundled ordering is preserved", () => {
		// given
		const pluginRoot = mkdtempSync(join(tmpdir(), "codex-rules-engine-consumption-"));
		tempDirectories.push(pluginRoot);
		mkdirSync(join(pluginRoot, "bundled-rules"), { recursive: true });
		writeFileSync(join(pluginRoot, "bundled-rules", "hephaestus.md"), "---\nalwaysApply: true\n---\nBundled\n");
		writeFileSync(
			join(pluginRoot, "bundled-rules", "windows-git-bash.md"),
			"---\nalwaysApply: true\n---\nWindows only\n",
		);

		// when
		const nonWindowsCandidates = findPluginBundledCandidates({ pluginRoot, platform: "darwin" });
		const windowsCandidates = findPluginBundledCandidates({ pluginRoot, platform: "win32" });

		// then
		expect(SOURCE_PRIORITY.get("plugin-bundled")).toBe(200);
		expect(nonWindowsCandidates.map((candidate) => candidate.relativePath)).toEqual([
			"bundled-rules/hephaestus.md",
		]);
		expect(windowsCandidates.map((candidate) => candidate.relativePath)).toEqual([
			"bundled-rules/hephaestus.md",
			"bundled-rules/windows-git-bash.md",
		]);
	});

	it("#given Codex rule parser and matcher edge cases #when imported from rules-engine #then current behavior is preserved", () => {
		// given
		const malformedRule = "---\nglobs: [\n---\nBody";

		// when
		const parsed = parseRule(malformedRule);
		const dotMatch = matchRule({
			frontmatter: { globs: "**/.env" },
			isSingleFile: false,
			pathBases: { projectRelative: "apps/web/.env", basename: ".env" },
		});
		const braceMatch = matchRule({
			frontmatter: { globs: "src/*.{ts,tsx}" },
			isSingleFile: false,
			pathBases: { projectRelative: "src/app.tsx", basename: "app.tsx" },
		});

		// then
		expect(parsed.diagnostic).toMatch(/^Malformed frontmatter:/);
		expect(parsed.body).toBe(malformedRule);
		expect(dotMatch).toEqual({ matched: true, reason: { kind: "glob", pattern: "**/.env" } });
		expect(braceMatch).toEqual({ matched: true, reason: { kind: "glob", pattern: "src/*.{ts,tsx}" } });
	});

	it("#given Codex scanner options #when imported from rules-engine #then scan depth and max files remain bounded", () => {
		// given
		const root = mkdtempSync(join(tmpdir(), "codex-rules-scanner-"));
		tempDirectories.push(root);
		mkdirSync(join(root, "a", "b"), { recursive: true });
		writeFileSync(join(root, "root.md"), "root");
		writeFileSync(join(root, "a", "nested.md"), "nested");
		writeFileSync(join(root, "a", "b", "too-deep.md"), "too deep");

		// when
		const depthOne = scanRuleFiles({ rootDir: root, maxDepth: 1 }).map((entry) => entry.path);
		const maxOne = scanRuleFiles({ rootDir: root, maxFiles: 1 });

		// then
		expect(depthOne).toContain(join(root, "root.md"));
		expect(depthOne).toContain(join(root, "a", "nested.md"));
		expect(depthOne).not.toContain(join(root, "a", "b", "too-deep.md"));
		expect(maxOne).toHaveLength(1);
	});
});

import { mkdirSync, mkdtempSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { scanRuleFiles } from "@oh-my-opencode/rules-engine/engine";

const tempDirectories: string[] = [];

afterEach(() => {
	for (const directory of tempDirectories.splice(0)) {
		rmSync(directory, { recursive: true, force: true });
	}
});

describe("scanRuleFiles", () => {
	it("#given more rule files than max #when scanning #then returns only capped files", () => {
		// given
		const root = mkdtempSync(join(tmpdir(), "codex-rules-scanner-"));
		tempDirectories.push(root);
		for (let index = 0; index < 5; index += 1) {
			writeFileSync(join(root, `rule-${index}.md`), `Rule ${index}\n`);
		}

		// when
		const files = scanRuleFiles({ rootDir: root, maxFiles: 2 });

		// then
		expect(files).toHaveLength(2);
	});

	it("#given rule files and an excluded directory #when scanning #then returns sorted non-excluded files", () => {
		// given
		const root = mkdtempSync(join(tmpdir(), "codex-rules-scanner-"));
		tempDirectories.push(root);
		mkdirSync(join(root, "dist"), { recursive: true });
		writeFileSync(join(root, "beta.md"), "Beta\n");
		writeFileSync(join(root, "alpha.md"), "Alpha\n");
		writeFileSync(join(root, "dist", "ignored.md"), "Ignored\n");

		// when
		const files = scanRuleFiles({ rootDir: root });

		// then
		expect(files.map((file) => file.path)).toEqual([join(root, "alpha.md"), join(root, "beta.md")]);
	});

	it("#given symlink loop #when scanning #then traversal terminates without duplicate files", () => {
		// given
		const root = mkdtempSync(join(tmpdir(), "codex-rules-scanner-"));
		tempDirectories.push(root);
		const nested = join(root, "nested");
		mkdirSync(nested, { recursive: true });
		writeFileSync(join(root, "root.md"), "Root\n");
		symlinkSync(root, join(nested, "loop"));

		// when
		const files = scanRuleFiles({ rootDir: root });

		// then
		expect(files.map((file) => file.path)).toEqual([join(root, "root.md")]);
	});
});

