		const repo = await bootstrapRepo(finalPlan());

		const result = await recordFinalReviewBlockers(repo, validArgs);

		expect(result.newGoal.successCriteria.map((criterion) => criterion.userModel).sort()).toEqual([
			"edge",
			"happy",
			"regression",
		]);
	});
});

