export async function readModelCatalog(env = process.env) {
	const catalogPath =
		env.LAZYCODEX_MODEL_CATALOG_PATH?.trim() || join(dirname(fileURLToPath(import.meta.url)), "..", "model-catalog.json");
	try {
		return parseCatalog(JSON.parse(await readFile(catalogPath, "utf8"))) ?? FALLBACK_CATALOG;
	} catch (error) {
		if (error instanceof Error) return FALLBACK_CATALOG;
		throw error;
	}
}

function parseCatalog(value) {
	if (!isRecord(value) || !isRecord(value.current) || !Array.isArray(value.managedProfiles)) return null;
	if (typeof value.version !== "string" || !isReasoningProfile(value.current)) return null;
	const managedProfiles = [];
	for (const profile of value.managedProfiles) {
		if (!isRecord(profile) || typeof profile.version !== "string" || !isRecord(profile.match)) return null;
		managedProfiles.push({ version: profile.version, match: profile.match });
	}
	return { version: value.version, current: value.current, managedProfiles, roles: isRecord(value.roles) ? value.roles : {} };
}

function isReasoningProfile(value) {
	return (
		isRecord(value) &&
		typeof value.model === "string" &&
		typeof value.model_context_window === "number" &&
		typeof value.model_reasoning_effort === "string" &&
		typeof value.plan_mode_reasoning_effort === "string"
	);
}

function isRecord(value) {
	return typeof value === "object" && value !== null && !Array.isArray(value);
}

import { lstat } from "node:fs/promises";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";

export async function configPaths({ env, cwd }) {
	const codexHome = resolve(env.CODEX_HOME?.trim() || join(homedir(), ".codex"));
	const paths = new Set([join(codexHome, "config.toml")]);
	for (const projectConfig of projectConfigPaths({ cwd, stopAt: homedir() })) {
		if (!(await isRegularFile(projectConfig))) continue;
		if (!(await isRegularDirectory(dirname(projectConfig)))) continue;
		paths.add(projectConfig);
	}
	return [...paths];
}

function projectConfigPaths({ cwd, stopAt }) {
	const paths = [];
	let current = resolve(cwd);
	const stop = resolve(stopAt);
	while (true) {
		paths.push(join(current, ".codex", "config.toml"));
		if (current === stop || current === dirname(current)) break;
		current = dirname(current);
	}
	return paths;
}

async function isRegularFile(path) {
	try {
		return (await lstat(path)).isFile();
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

async function isRegularDirectory(path) {
	try {
		return (await lstat(path)).isDirectory();
	} catch (error) {
		if (error instanceof Error && "code" in error && error.code === "ENOENT") return false;
		throw error;
	}
}

const CONTEXT7_HEADER = "[mcp_servers.context7]";

export function removeStaleContext7PlaceholderMcpServer(config) {
	return removeSections(config, (section) => section.header === CONTEXT7_HEADER && isContext7PlaceholderSection(section.text));
}

function isContext7PlaceholderSection(sectionText) {
	const args = readStringArraySetting(sectionText, "args");
	if (args === null || !args.includes("@upstash/context7-mcp")) return false;
	const apiKey = valueAfter(args, "--api-key");
	return apiKey !== null && isPlaceholderApiKey(apiKey);
}

function valueAfter(values, key) {
	const index = values.indexOf(key);
	return index >= 0 ? values[index + 1] ?? null : null;
}

function isPlaceholderApiKey(value) {
	return /^your[-_ ]?api[-_ ]?key$/i.test(value);
}

function readStringArraySetting(sectionText, key) {
	for (const line of sectionText.split("\n")) {
		if (!new RegExp(`^\\s*${key}\\s*=`).test(line)) continue;
		const assignmentIndex = line.indexOf("=");
		if (assignmentIndex === -1) return null;
		return parseTomlStringArray(stripUnquotedInlineComment(line.slice(assignmentIndex + 1)).trim());
	}
	return null;
}

function parseTomlStringArray(value) {
	if (!value.startsWith("[") || !value.endsWith("]")) return null;
	const items = [];
	let index = 1;
	while (index < value.length - 1) {
		const char = value[index];
		if (char === "\"" || char === "'") {
			const parsed = parseTomlString(value, index);
			if (parsed === null) return null;
			items.push(parsed.value);
			index = parsed.nextIndex;
			continue;
		}
		index += 1;
	}
	return items;
}

function parseTomlString(input, startIndex) {
	const quote = input[startIndex];
	let value = "";
	let index = startIndex + 1;
	while (index < input.length) {
		const char = input[index];
		if (quote === "\"" && char === "\\") {
			const next = input[index + 1];
			if (next === undefined) return null;
			value += next;
			index += 2;
			continue;
		}
		if (char === quote) return { value, nextIndex: index + 1 };
		value += char;
		index += 1;
	}
	return null;
}

function stripUnquotedInlineComment(line) {
	let quote = null;
	let index = 0;
	while (index < line.length) {
		const char = line[index];
		if (quote === "\"") {
			if (char === "\\") {
				index += 2;
				continue;
			}
			if (char === "\"") quote = null;
			index += 1;
			continue;
		}
		if (quote === "'") {
			if (char === "'") quote = null;
			index += 1;
			continue;
		}
		if (char === "\"" || char === "'") {
			quote = char;
			index += 1;
			continue;
		}
		if (char === "#") return line.slice(0, index);
		index += 1;
	}
	return line;
}

function removeSections(config, shouldRemove) {
	return splitSections(config)
		.filter((section) => !shouldRemove(section))
		.map((section) => section.text)
		.join("")
		.replace(/\n{3,}/g, "\n\n");
}

function splitSections(config) {
	const lines = config.match(/[^\n]*\n?|$/g) ?? [];
	const sections = [];
	let current = { header: null, text: "" };
	for (const line of lines) {
		if (line.length === 0) break;
		const header = tableHeader(line);
		if (header !== null) {
			if (current.text.length > 0) sections.push(current);
			current = { header, text: line };
		} else {
			current = { ...current, text: current.text + line };
		}
	}
	if (current.text.length > 0) sections.push(current);
	return sections;
}

function tableHeader(line) {
	const trimmed = stripUnquotedInlineComment(line).trim();
	if (!trimmed.startsWith("[") || !trimmed.endsWith("]") || trimmed.startsWith("[[")) return null;
	return trimmed;
}

const MULTI_AGENT_MODE_KEY = "multi_agent_mode";

export function removeUnsupportedRootMultiAgentMode(config) {
	const lines = config.split(/\n/);
	const output = [];
	let inRoot = true;
	let changed = false;
	for (const line of lines) {
		const sectionHeader = isSectionHeader(line);
		if (inRoot && isRootSetting(line, MULTI_AGENT_MODE_KEY)) {
			changed = true;
			continue;
		}
		output.push(line);
		if (sectionHeader) inRoot = false;
	}
	return changed ? output.join("\n") : config;
}

function isSectionHeader(line) {
	const trimmed = stripUnquotedInlineComment(line).trim();
	return trimmed.startsWith("[") && trimmed.endsWith("]");
}

function isRootSetting(line, key) {
	const trimmed = line.trimStart();
	if (trimmed.startsWith("#") || trimmed.startsWith("[")) return false;
	const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=/);
	return match?.[1] === key;
}

function stripUnquotedInlineComment(line) {
	let quote = null;
	let index = 0;
	while (index < line.length) {
		const char = line[index];
		if (quote === "\"") {
			if (char === "\\") {
				index += 2;
				continue;
			}
			if (char === "\"") quote = null;
			index += 1;
			continue;
		}
		if (quote === "'") {
			if (char === "'") quote = null;
			index += 1;
			continue;
		}
		if (char === "\"" || char === "'") {
			quote = char;
			index += 1;
			continue;
		}
		if (char === "#") return line.slice(0, index);
		index += 1;
	}
	return line;
}

/**
 * Runtime migration: force `[features.multi_agent_v2]` to `enabled = false`.
 *
 * Runs on every Codex SessionStart (via auto-update's config migration) so
 * multi-agent V2 stays off regardless of how it was turned on: an
 * installer-forced `enabled = true`, a missing `enabled` key the runtime
 * would resolve per model, or the `[features]` boolean shorthand
 * `multi_agent_v2 = true` (removed here because a boolean key and a
 * `[features.multi_agent_v2]` table for the same name are conflicting TOML).
 *
 * Upstream basis: openai/codex#26753 — with the flag on, EVERY turn fails
 * with a 400 ("spawn_agent declares encrypted parameters but is not
 * configured for encrypted tool use by this model"), even on prompts that
 * never touch subagents. OpenAI closed it NOT_PLANNED stating V2 is under
 * development, not recommended, and bug reports are not accepted. Same
 * failure class still being reported (openai/codex#27205).
 */
const MANAGED_COMMENT_MARKER = "openai/codex#26753";
const MANAGED_DISABLE_COMMENT = [
	"# Managed by LazyCodex: multi_agent_v2 is re-disabled on every Codex session start",
	`# because enabling it fails every turn with HTTP 400 (${MANAGED_COMMENT_MARKER}).`,
	"# Opt out: LAZYCODEX_CONFIG_MIGRATION_DISABLED=1 (or OMO_CODEX_CONFIG_MIGRATION_DISABLED=1).",
	"",
].join("\n");

export function forceDisableMultiAgentV2(config) {
	let result = removeFeaturesShorthand(config);
	const section = findSection(result, "[features.multi_agent_v2]");

	if (!section) {
		return ensureManagedComment(appendDisabledSection(result));
	}

	const enabledTruePattern = /^(\s*)enabled\s*=\s*true[ \t]*(#[^\n]*)?$/m;
	if (enabledTruePattern.test(section.text)) {
		const patched = section.text.replace(enabledTruePattern, (_match, indent, comment) => comment ? `${indent}enabled = false ${comment}` : `${indent}enabled = false`);
		return ensureManagedComment(result.slice(0, section.start) + patched + result.slice(section.end));
	}

	if (/^\s*enabled\s*=\s*false[ \t]*(?:#[^\n]*)?$/m.test(section.text)) return result;

	const headerEnd = section.text.indexOf("\n");
	const insertAt = headerEnd === -1 ? section.text.length : headerEnd + 1;
	const patched = `${section.text.slice(0, insertAt)}${headerEnd === -1 ? "\n" : ""}enabled = false\n${section.text.slice(insertAt)}`;
	return ensureManagedComment(result.slice(0, section.start) + patched + result.slice(section.end));
}

function ensureManagedComment(config) {
	if (config.includes(MANAGED_COMMENT_MARKER)) return config;
	const section = findSection(config, "[features.multi_agent_v2]");
	if (!section) return config;
	return config.slice(0, section.start) + MANAGED_DISABLE_COMMENT + config.slice(section.start);
}

function removeFeaturesShorthand(config) {
	const section = findSection(config, "[features]");
	if (!section) return config;

	const shorthandPattern = /^\s*multi_agent_v2\s*=\s*(?:true|false)[ \t]*(?:#[^\n]*)?[ \t]*\n?/m;
	if (!shorthandPattern.test(section.text)) return config;

	const patched = section.text.replace(shorthandPattern, "");
	return config.slice(0, section.start) + patched + config.slice(section.end);
}

function appendDisabledSection(config) {
	const trimmed = config.trimEnd();
	const prefix = trimmed.length === 0 ? "" : `${trimmed}\n\n`;
	return `${prefix}[features.multi_agent_v2]\nenabled = false\n`;
}

// Strips a trailing # comment from a TOML line fragment (best-effort; quoted keys containing # are out of scope).
function stripTrailingComment(line) {
	const idx = line.indexOf("#");
	return idx === -1 ? line : line.slice(0, idx).trim();
}

function findSection(config, headerLine) {
	const lines = config.match(/[^\n]*\n?|$/g) ?? [];
	let offset = 0;
	let start = -1;
	for (const line of lines) {
		if (line.length === 0) break;
		const trimmed = line.trim();
		if (start === -1) {
			if (stripTrailingComment(trimmed) === headerLine) start = offset;
		} else {
			const bare = stripTrailingComment(trimmed);
			if (bare.startsWith("[") && bare.endsWith("]")) {
				return { start, end: offset, text: config.slice(start, offset) };
			}
		}
		offset += line.length;
	}
	if (start === -1) return null;
	return { start, end: config.length, text: config.slice(start) };
}

export const MANAGED_KEYS = ["model", "model_context_window", "model_reasoning_effort", "plan_mode_reasoning_effort"];

export function ensureCodexReasoningConfig(config, profile) {
	let next = replaceOrInsertRootSetting(config, "model", JSON.stringify(profile.model));
	next = replaceOrInsertRootSetting(next, "model_context_window", profile.model_context_window.toString());
	next = replaceOrInsertRootSetting(next, "model_reasoning_effort", JSON.stringify(profile.model_reasoning_effort));
	next = replaceOrInsertRootSetting(next, "plan_mode_reasoning_effort", JSON.stringify(profile.plan_mode_reasoning_effort));
	return next;
}

export function readRootSettings(config) {
	const settings = {};
	for (const line of config.split(/\n/)) {
		if (isSectionHeader(line)) break;
		for (const key of MANAGED_KEYS) {
			if (!isRootSetting(line, key)) continue;
			const value = parseTomlScalar(line.slice(line.indexOf("=") + 1));
			if (value !== undefined) settings[key] = value;
		}
	}
	return settings;
}

function parseTomlScalar(value) {
	const trimmed = value.trim();
	if (trimmed.startsWith('"') && trimmed.endsWith('"')) {
		try {
			return JSON.parse(trimmed);
		} catch (error) {
			if (error instanceof SyntaxError) return undefined;
			throw error;
		}
	}
	const numeric = Number(trimmed);
	return Number.isFinite(numeric) ? numeric : undefined;
}

function replaceOrInsertRootSetting(config, key, value) {
	const lines = config.split(/\n/);
	const output = [];
	let replaced = false;
	let inserted = false;
	let inRoot = true;
	for (const line of lines) {
		const sectionHeader = isSectionHeader(line);
		if (inRoot && !inserted && sectionHeader) {
			if (!replaced) output.push(`${key} = ${value}`);
			inserted = true;
		}
		if (inRoot && isRootSetting(line, key)) {
			if (!replaced) {
				output.push(`${key} = ${value}`);
				replaced = true;
			}
			continue;
		}
		output.push(line);
		if (sectionHeader) inRoot = false;
	}
	if (!replaced && !inserted) output.push(`${key} = ${value}`);
	return output.join("\n");
}

function isSectionHeader(line) {
	const trimmed = stripUnquotedInlineComment(line).trim();
	return trimmed.startsWith("[") && trimmed.endsWith("]");
}

function isRootSetting(line, key) {
	const trimmed = line.trimStart();
	if (trimmed.startsWith("#") || trimmed.startsWith("[")) return false;
	const match = trimmed.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=/);
	return match?.[1] === key;
}

function stripUnquotedInlineComment(line) {
	let quote = null;
	let index = 0;
	while (index < line.length) {
		const char = line[index];
		if (quote === "\"") {
			if (char === "\\") {
				index += 2;
				continue;
			}
			if (char === "\"") quote = null;
			index += 1;
			continue;
		}
		if (quote === "'") {
			if (char === "'") quote = null;
			index += 1;
			continue;
		}
		if (char === "\"" || char === "'") {
			quote = char;
			index += 1;
			continue;
		}
		if (char === "#") return line.slice(0, index);
		index += 1;
	}
	return line;
}

