	].filter((specifier) => !specifier.startsWith("node:"));

	// then
	assert(bundle.length > 0, "bootstrap bundle must not be empty");
	assert.deepEqual(externalSpecifiers, [], "bootstrap dist must bundle everything except node: built-ins");
});

